import { useEffect, useRef, useState, type ChangeEvent, type CSSProperties, type FormEvent, type ReactNode } from 'react'
import { api, ApiError } from './api'
import type { AIResponseRecord, ActivityItem, AdminConfigurationRecord, AdminUser, AgentRecord, AnalyticsSnapshot, AuditEvent, DashboardOverview, DocumentRecord, EvaluationSnapshot, MeetingRecord, ModelProfile, ModelScorecard, OperatingDecision, OperatingIntelligenceSnapshot, PolicyRecord, ProductHealthSnapshot, ProductLearningSnapshot, ProactiveAlert, ReadinessSnapshot, RiskItem, SessionUser, ValueIntelligenceSnapshot, WorkflowRecord } from './types'
import { Icon } from './components/Icon'
import { Avatar, Button, ClassificationBadge, EmptyState, ErrorNotice, LoadingBlock, MiniSparkline, ProgressBar, SectionHeading, StatusBadge } from './components/Ui'
import { relativeTime, shortNumber } from './utils'

const formatDate = (value: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value))

function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section> }
function PanelTitle({ icon, title, detail, action }: { icon?: string; title: string; detail?: string; action?: ReactNode }) { return <div className="panel-title"> <div className="panel-title-left">{icon && <span className="panel-title-icon"><Icon name={icon} size={16} /></span>}<div><h3>{title}</h3>{detail && <p>{detail}</p>}</div></div>{action}</div> }

function MetricCard({ metric }: { metric: DashboardOverview['metrics'][number] }) {
  const trendUp = metric.trend >= 0
  return <div className={`metric-card metric-${metric.tone}`}><div className="metric-top"><span className="metric-icon"><Icon name={metric.icon} size={18} /></span><span className="metric-menu"><Icon name="more" size={16} /></span></div><div className="metric-value">{metric.value}</div><div className="metric-label">{metric.label}</div><div className={`metric-detail ${metric.trend === 0 ? 'neutral' : trendUp ? 'up' : 'down'}`}>{metric.trend !== 0 && <Icon name={trendUp ? 'arrow-up-right' : 'arrow-down-right'} size={13} />}{metric.detail}</div></div>
}

function HealthRing({ value }: { value: number }) {
  return <div className="health-ring" style={{ '--ring-value': `${value * 3.6}deg` } as CSSProperties}><div className="health-ring-inner"><strong>{value}</strong><span>/ 100</span></div></div>
}

function ActivityIcon({ type }: { type: ActivityItem['type'] }) {
  const names: Record<ActivityItem['type'], string> = { ai: 'sparkles', document: 'file-text', agent: 'bot', workflow: 'workflow', security: 'shield-check', meeting: 'calendar' }
  return <span className={`activity-icon activity-${type}`}><Icon name={names[type]} size={15} /></span>
}

function ActivityFeed({ items }: { items: ActivityItem[] }) {
  return <div className="activity-feed">{items.map((item) => <div className="activity-row" key={item.id}><ActivityIcon type={item.type} /><div className="activity-copy"><strong>{item.title}</strong><span>{item.description}</span><small>{item.actor} · {relativeTime(item.timestamp)}</small></div><span className={`activity-status activity-${item.status}`}><i /></span></div>)}</div>
}

function RiskList({ risks, onSelect }: { risks: RiskItem[]; onSelect?: (risk: RiskItem) => void }) {
  return <div className="risk-list">{risks.map((risk) => <button className="risk-row" key={risk.id} onClick={() => onSelect?.(risk)}><span className={`risk-symbol risk-${risk.severity}`}><Icon name={risk.kind === 'conflict' ? 'git-branch' : risk.kind === 'stale' ? 'clock' : risk.kind === 'gap' ? 'help' : 'shield-alert'} size={16} /></span><span className="risk-copy"><strong>{risk.title}</strong><small>{risk.description}</small><em>{risk.owner} · {risk.due}</em></span><Icon name="chevron-right" size={15} className="row-chevron" /></button>)}</div>
}

export function CommandCenter({ overview, user, onNavigate, onToast }: { overview: DashboardOverview; user: SessionUser; onNavigate: (view: string) => void; onToast: (message: string) => void }) {
  const [alerts, setAlerts] = useState<ProactiveAlert[]>([])
  const [showGuide, setShowGuide] = useState(() => typeof window === 'undefined' || window.localStorage.getItem('smart-corp:first-session-guide') !== 'dismissed')
  useEffect(() => { api.alerts().then(({ items }) => setAlerts(items)).catch(() => setAlerts([])) }, [])
  const openAlert = (alert: ProactiveAlert) => { const target = alert.kind === 'approval' ? 'automations' : alert.kind === 'expiry' ? 'knowledge' : 'knowledge-intelligence'; onNavigate(target) }
  const dismissGuide = () => { setShowGuide(false); window.localStorage.setItem('smart-corp:first-session-guide', 'dismissed') }
  const [selectedRisk, setSelectedRisk] = useState<RiskItem | null>(null)
  return <div className="view-stack">
    <div className="command-hero"><div className="hero-copy"><div className="eyebrow eyebrow-light">TUESDAY, AUGUST 25, 2026 <span className="live-dot" /> LIVE INTELLIGENCE</div><h1>Good morning, {user.displayName.split(' ')[0]}.</h1><p>Your organization is operating with strong signal. Here’s what needs your attention today.</p><div className="hero-actions"><Button icon="sparkles" onClick={() => onNavigate('ai-workspace')}>Ask your workspace</Button><button className="text-action" onClick={() => onNavigate('analytics')}>View intelligence report <Icon name="arrow-right" size={15} /></button></div></div><div className="hero-signal"><div className="signal-label"><span className="signal-pulse" /> ORGANIZATION SIGNAL</div><HealthRing value={overview.organization.healthScore} /><span className="signal-caption">Healthy knowledge foundation</span><span className="signal-updated">Updated {relativeTime(overview.lastUpdated)}</span></div></div>
    {showGuide && <div className="first-session-guide"><div className="first-session-heading"><span className="first-session-icon"><Icon name="sparkles" size={17} /></span><span><strong>Start with trusted intelligence</strong><small>Ask a question, verify the evidence, then take the next safe action.</small></span><button onClick={dismissGuide} aria-label="Dismiss first session guide"><Icon name="x" size={15} /></button></div><div className="first-session-steps"><button onClick={() => onNavigate('ai-workspace')}><span>01</span><strong>Ask</strong><small>Search authorized knowledge in plain language.</small><Icon name="arrow-right" size={14} /></button><button onClick={() => onNavigate('knowledge')}><span>02</span><strong>Verify</strong><small>Open the source, owner, version and trust signals.</small><Icon name="arrow-right" size={14} /></button><button onClick={() => onNavigate('automations')}><span>03</span><strong>Act safely</strong><small>Actions are confirmed, approved and audited.</small><Icon name="arrow-right" size={14} /></button></div></div>}
    <div className="metric-grid">{overview.metrics.map((metric) => <MetricCard metric={metric} key={metric.label} />)}</div>
    {alerts.length > 0 && <div className="proactive-strip"><div className="proactive-heading"><span className="proactive-icon"><Icon name="zap" size={16} /></span><span><strong>Proactive intelligence</strong><small>Evidence-backed signals to review</small></span></div>{alerts.slice(0, 3).map((alert) => <button className="proactive-alert" key={alert.id} onClick={() => openAlert(alert)}><span className={`proactive-severity proactive-${alert.severity}`} /><span><strong>{alert.title}</strong><small>{alert.description}</small></span><Icon name="arrow-up-right" size={14} /></button>)}</div>}
    <div className="dashboard-grid dashboard-grid-top"><Panel className="health-panel"><PanelTitle icon="gauge" title="Knowledge health" detail="Source quality across your organization" action={<button className="panel-link" onClick={() => onNavigate('knowledge-intelligence')}>View details <Icon name="arrow-up-right" size={14} /></button>} /><div className="health-content"><div className="health-breakdown"><div className="health-score"><strong>{overview.organization.healthScore}%</strong><span>Overall health score</span></div><MiniSparkline values={overview.healthFactors.map((factor) => factor.value)} color="#8167e8" fill /></div><div className="health-factors">{overview.healthFactors.map((factor) => <div key={factor.label}><span className={`factor-dot factor-${factor.tone}`} /><span>{factor.label}</span><strong>{factor.value}%</strong></div>)}</div></div><div className="health-foot"><span><Icon name="database" size={14} /> {overview.organization.documentCount.toLocaleString()} sources connected</span><span><Icon name="clock" size={14} /> {overview.reviewDue} reviews due this week</span></div></Panel>
      <Panel className="network-panel"><PanelTitle icon="network" title="Agent network" detail="Live intelligence routing" action={<button className="panel-link" onClick={() => onNavigate('ai-agents')}>Manage agents <Icon name="arrow-up-right" size={14} /></button>} /><div className="agent-network">{overview.agentNetwork.map((agent) => <button className="network-agent" key={agent.id} onClick={() => onNavigate('ai-agents')}><span className="network-avatar" style={{ background: agent.color }}>{agent.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><span className="network-agent-copy"><strong>{agent.name}</strong><small>{agent.category} · {agent.status}</small><ProgressBar value={agent.usage} color={agent.color} /></span><span className="network-usage">{agent.usage}%<small>load</small></span></button>)}</div></Panel></div>
    <div className="dashboard-grid dashboard-grid-bottom"><Panel><PanelTitle icon="triangle-alert" title="Needs your attention" detail="Prioritized by policy impact" action={<button className="icon-button" aria-label="Filter risks" onClick={() => onToast('Risk filters opened')}><Icon name="sliders" size={16} /></button>} /><RiskList risks={overview.risks} onSelect={setSelectedRisk} /><button className="panel-footer-link" onClick={() => onNavigate('knowledge-intelligence')}>Open knowledge intelligence <Icon name="arrow-right" size={14} /></button></Panel><Panel><PanelTitle icon="activity" title="Recent activity" detail="Across your organization" action={<button className="panel-link" onClick={() => onNavigate('history')}>View history <Icon name="arrow-up-right" size={14} /></button>} /><ActivityFeed items={overview.activity} /></Panel><Panel className="department-panel"><PanelTitle icon="bar-chart" title="Department signal" detail="Queries and trust · last 30 days" action={<button className="icon-button" aria-label="More department options" onClick={() => onToast('Department signal options opened')}><Icon name="more" size={17} /></button>} /><div className="department-bars">{overview.departments.map((department) => <div className="department-row" key={department.name}><div className="department-label"><span>{department.name}</span><strong>{shortNumber(department.queries)}</strong></div><div className="department-bar-line"><ProgressBar value={Math.min(100, department.queries / 42)} color={department.color} /><small>{department.trust} trust</small></div></div>)}</div></Panel></div>
    {selectedRisk && <div className="modal-backdrop" onClick={() => setSelectedRisk(null)}><div className="side-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setSelectedRisk(null)}><Icon name="x" size={18} /></button><div className={`large-risk-symbol risk-${selectedRisk.severity}`}><Icon name={selectedRisk.kind === 'conflict' ? 'git-branch' : 'triangle-alert'} size={22} /></div><div className="eyebrow">KNOWLEDGE RISK</div><h2>{selectedRisk.title}</h2><p>{selectedRisk.description}</p><div className="detail-list"><div><span>Severity</span><StatusBadge tone={selectedRisk.severity === 'high' ? 'danger' : selectedRisk.severity === 'medium' ? 'warning' : 'info'}>{selectedRisk.severity}</StatusBadge></div><div><span>Owner</span><strong>{selectedRisk.owner}</strong></div><div><span>Signal</span><strong>{selectedRisk.due}</strong></div></div><Button icon="arrow-right" onClick={() => { setSelectedRisk(null); onNavigate('knowledge-intelligence') }}>Open intelligence queue</Button></div></div>}
  </div>
}

interface ConversationTurn { question: string; response: AIResponseRecord }

export function AIWorkspace({ initialAgentId, onToast }: { initialAgentId?: string; onToast: (message: string) => void }) {
  const [agents, setAgents] = useState<AgentRecord[]>([])
  const [agentId, setAgentId] = useState(initialAgentId ?? '')
  const [question, setQuestion] = useState('')
  const [turns, setTurns] = useState<ConversationTurn[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [conversationId, setConversationId] = useState<string>()
  const [sourceMode, setSourceMode] = useState<'internal' | 'structured' | 'web' | 'mixed'>('internal')
  const [showSources, setShowSources] = useState(true)
  const [feedback, setFeedback] = useState<Record<string, string>>({})
  const inputRef = useRef<HTMLTextAreaElement>(null)
  useEffect(() => { api.agents().then(({ items }) => { setAgents(items); if (!agentId && items[0]) setAgentId(items[0].id) }).catch(() => undefined) }, [])
  useEffect(() => { inputRef.current?.focus() }, [])
  const activeAgent = agents.find((agent) => agent.id === agentId) ?? agents[0]
  const ask = async (event?: FormEvent) => {
    event?.preventDefault(); if (!question.trim() || loading) return
    setLoading(true); setError('')
    try { const result = await api.ask(question, agentId || undefined, conversationId, sourceMode); setTurns((current) => [...current, { question: question.trim(), response: result.response }]); setConversationId(result.conversationId); setQuestion(''); onToast('Response verified against permissioned sources') } catch (caught) { setError(caught instanceof ApiError ? caught.message : 'The AI gateway could not complete this request.') } finally { setLoading(false) }
  }
  const createGap = async (response: AIResponseRecord) => { try { const result = await api.executeTool('create_knowledge_gap', { question: response.question, impact: 'medium' }); onToast(result.message) } catch (caught) { onToast(caught instanceof Error ? caught.message : 'The knowledge gap tool could not run') } }
  const sendFeedback = async (responseId: string, feedbackType: 'helpful' | 'not_helpful') => { setFeedback((current) => ({ ...current, [responseId]: feedbackType === 'not_helpful' ? 'not-helpful' : feedbackType })); try { await api.feedback(responseId, feedbackType); onToast('Feedback recorded for evaluation and knowledge improvement') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Feedback could not be recorded') } }
  const suggestions = ['What is our policy for privileged access reviews?', 'What approvals are required for international travel?', 'How should customer data be shared externally?']
  return <div className="workspace-layout"><div className="workspace-main"><div className="workspace-header"><div><div className="eyebrow">INTELLIGENCE WORKSPACE</div><h1>Ask your enterprise knowledge</h1><p>Permission-aware answers with evidence you can verify.</p></div><div className="workspace-header-actions"><select className="source-select" value={sourceMode} onChange={(event) => setSourceMode(event.target.value as typeof sourceMode)} aria-label="Select AI source scope"><option value="internal">Internal knowledge</option><option value="structured">Structured metrics</option><option value="mixed">Internal + data</option><option value="web">Web research</option></select><StatusBadge tone="success">Grounding on</StatusBadge><button className="icon-button" onClick={() => onToast('Workspace actions opened')}><Icon name="more" size={18} /></button></div></div><div className="conversation-shell">{turns.length === 0 && !loading ? <div className="workspace-empty"><div className="ai-orbit"><span /><span /><span /><Icon name="sparkles" size={25} /></div><h2>Where should we look first?</h2><p>Ask about policies, processes, risks or any approved organizational knowledge.</p><div className="suggestion-grid">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => setQuestion(suggestion)}><span>{suggestion}</span><Icon name="arrow-up-right" size={15} /></button>)}</div></div> : <div className="thread">{turns.map((turn) => <div className="turn" key={turn.response.id}><div className="user-message"><Avatar initials="MC" tone="slate" size="sm" /><div><span className="message-label">You</span><p>{turn.question}</p></div></div><div className="ai-message"><Avatar initials={activeAgent?.initials ?? 'AI'} tone="violet" size="sm" /><div className="ai-message-body"><div className="message-meta"><span className="message-label">{turn.response.agent}</span><StatusBadge tone={turn.response.trust.label === 'Verified' ? 'success' : turn.response.trust.label === 'Needs review' ? 'warning' : 'neutral'}>{turn.response.trust.label}</StatusBadge><span className="response-meta">{turn.response.latencyMs}ms · {turn.response.model}</span><StatusBadge tone="violet" dot={false}>{turn.response.responseType.replaceAll('_', ' ')}</StatusBadge></div><div className="response-plan">{turn.response.progress.slice(0, 4).map((step, index) => <span className={index === turn.response.progress.slice(0, 4).length - 1 ? 'current' : ''} key={step}><i>{index + 1}</i>{step}</span>)}</div><p>{turn.response.answer}</p>{turn.response.structuredData && <div className="response-table-wrap"><div className="response-table-title"><Icon name="database" size={13} /> {turn.response.structuredData.title}<span>as of {turn.response.structuredData.asOf}</span></div><table><thead><tr>{turn.response.structuredData.columns.map((column) => <th key={column}>{column}</th>)}</tr></thead><tbody>{turn.response.structuredData.rows.map((row, rowIndex) => <tr key={`${rowIndex}-${row[0]}`}>{row.map((cell, cellIndex) => <td key={`${rowIndex}-${cellIndex}`}>{cell}</td>)}</tr>)}</tbody></table><small>{turn.response.structuredData.sourceLabel}</small></div>}{turn.response.trust.warnings.length > 0 && <div className="warning-callout"><Icon name="triangle-alert" size={15} /><span>{turn.response.trust.warnings[0]}</span></div>}<div className="response-actions"><button onClick={() => setShowSources(true)}><Icon name="book" size={14} /> {turn.response.citations.length} sources</button>{turn.response.trust.label === 'Insufficient evidence' && <button onClick={() => void createGap(turn.response)}><Icon name="plus" size={14} /> Create gap</button>}<button className={feedback[turn.response.id] === 'helpful' ? 'selected' : ''} onClick={() => void sendFeedback(turn.response.id, 'helpful')}><Icon name="thumbs-up" size={14} /></button><button className={feedback[turn.response.id] === 'not-helpful' ? 'selected' : ''} onClick={() => void sendFeedback(turn.response.id, 'not_helpful')}><Icon name="thumbs-down" size={14} /></button><button onClick={() => navigator.clipboard?.writeText(turn.response.answer).then(() => onToast('Answer copied to clipboard'))}><Icon name="copy" size={14} /> Copy</button></div><div className="follow-up-list">{turn.response.followUps.map((followUp) => <button key={followUp} onClick={() => setQuestion(followUp)}>{followUp}<Icon name="arrow-up-right" size={12} /></button>)}</div></div></div></div>)}</div>}{loading && <div className="ai-message loading-message"><Avatar initials={activeAgent?.initials ?? 'AI'} tone="violet" size="sm" /><div><span className="message-label">{activeAgent?.name ?? 'Knowledge Navigator'}</span><div className="thinking"><i /><i /><i /><span>Retrieving permissioned evidence…</span></div></div></div>}{error && <ErrorNotice message={error} />}</div><form className="composer" onSubmit={ask}><div className="composer-agent"><span className="composer-agent-dot" style={{ background: activeAgent?.accent === 'teal' ? '#21b6a8' : '#8167e8' }} /><select value={agentId} onChange={(event) => setAgentId(event.target.value)} aria-label="Choose agent">{agents.map((agent) => <option value={agent.id} key={agent.id}>{agent.name}</option>)}</select><Icon name="chevron-down" size={14} /></div><textarea ref={inputRef} value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); void ask() } }} placeholder="Ask anything about your organization…" rows={1} /><button type="button" className="composer-attach" aria-label="Attach source" onClick={() => onToast('Attach a source from Knowledge; uploads are security-scanned before indexing')}><Icon name="paperclip" size={17} /></button><button type="submit" className="composer-send" disabled={!question.trim() || loading} aria-label="Send question"><Icon name="send" size={17} /></button><small>AI can make mistakes. Verify important decisions against the cited source.</small></form></div><aside className={`evidence-rail ${showSources ? '' : 'rail-collapsed'}`}><div className="evidence-header"><div><div className="eyebrow">EVIDENCE</div><h3>Source panel</h3></div><button className="icon-button" onClick={() => setShowSources((value) => !value)}><Icon name={showSources ? 'panel-left-close' : 'panel-left-open'} size={17} /></button></div>{turns.length === 0 ? <div className="evidence-empty"><div className="evidence-empty-icon"><Icon name="shield-check" size={20} /></div><strong>Trust, not just answers</strong><p>Sources, evidence and policy signals will appear here after you ask a question.</p><div className="trust-legend"><span><i className="legend-dot legend-violet" /> Retrieval relevance</span><span><i className="legend-dot legend-teal" /> Grounding confidence</span><span><i className="legend-dot legend-amber" /> Policy confidence</span></div></div> : <div className="evidence-content">{turns[turns.length - 1].response.trust.overall !== null && <div className="trust-card"><div className="trust-card-head"><span>Overall trust</span><strong>{turns[turns.length - 1].response.trust.overall}<small>/100</small></strong></div><ProgressBar value={turns[turns.length - 1].response.trust.overall ?? 0} color="#21b6a8" height={7} /><div className="trust-signals"><span>Retrieval <b>{turns[turns.length - 1].response.trust.retrieval}</b></span><span>Grounding <b>{turns[turns.length - 1].response.trust.grounding}</b></span><span>Policy <b>{turns[turns.length - 1].response.trust.policy}</b></span></div></div>}<div className="source-list">{turns[turns.length - 1].response.citations.map((citation, index) => <button className="source-card" key={citation.id} onClick={() => onToast(`Opening ${citation.title} in a permission-checked view`)}><div className="source-card-top"><span className="source-index">0{index + 1}</span><ClassificationBadge value={citation.classification} /><span className="source-relevance">{Math.round(citation.relevance * 100)}%</span></div><strong>{citation.title}</strong><span className="source-section">{citation.section}{citation.page ? ` · p. ${citation.page}` : ''}</span><p>{citation.excerpt}</p><small><Icon name="user" size={12} /> {citation.owner} · updated {relativeTime(citation.updatedAt)}</small></button>)}</div></div>}</aside></div>
}

function documentIcon(type: string) { return type === 'PDF' ? 'file-text' : type === 'XLSX' || type === 'CSV' ? 'file-spreadsheet' : type === 'PPTX' ? 'file-bar-chart' : 'file-code' }
function DocumentStatus({ status }: { status: DocumentRecord['status'] }) { const config: Record<DocumentRecord['status'], { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = { ready: { label: 'Ready', tone: 'success' }, processing: { label: 'Processing', tone: 'info' }, review: { label: 'Review due', tone: 'warning' }, failed: { label: 'Failed', tone: 'danger' } }; return <StatusBadge tone={config[status].tone}>{config[status].label}</StatusBadge> }

export function Knowledge({ onToast }: { onToast: (message: string) => void }) {
  const [documents, setDocuments] = useState<DocumentRecord[]>([]); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [classification, setClassification] = useState('all'); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [selected, setSelected] = useState<DocumentRecord | null>(null); const [uploadOpen, setUploadOpen] = useState(false)
  const load = () => { setLoading(true); setError(''); api.documents({ search: search || undefined, status, classification }).then(({ items }) => setDocuments(items)).catch((caught) => setError(caught instanceof Error ? caught.message : 'Unable to load documents.')).finally(() => setLoading(false)) }
  useEffect(() => { load() }, [search, status, classification])
  const readyCount = documents.filter((document) => document.status === 'ready').length
  return <div className="view-stack"><SectionHeading eyebrow="KNOWLEDGE LIBRARY" title="Trusted knowledge, in one place" description="Ingest, curate and govern the sources your teams rely on." action={<div className="heading-actions"><Button icon="upload" onClick={() => setUploadOpen(true)}>Upload source</Button><button className="icon-button" onClick={load} aria-label="Refresh library"><Icon name="refresh" size={17} /></button></div>} /><div className="knowledge-overview"><div className="knowledge-stat"><span className="knowledge-stat-icon violet"><Icon name="database" size={18} /></span><div><strong>{documents.length || '—'}</strong><span>Visible sources</span></div></div><div className="knowledge-stat"><span className="knowledge-stat-icon teal"><Icon name="file-check" size={18} /></span><div><strong>{readyCount || '—'}</strong><span>Ready for AI</span></div></div><div className="knowledge-stat"><span className="knowledge-stat-icon amber"><Icon name="clock" size={18} /></span><div><strong>{documents.filter((document) => document.status === 'review').length || '—'}</strong><span>Review queue</span></div></div><div className="knowledge-stat"><span className="knowledge-stat-icon blue"><Icon name="shield-check" size={18} /></span><div><strong>{documents.length ? `${Math.round(documents.filter((d) => d.trust > 0).reduce((sum, d) => sum + d.trust, 0) / Math.max(1, documents.filter((d) => d.trust > 0).length))}%` : '—'}</strong><span>Avg. source trust</span></div></div></div><Panel className="library-panel"><div className="library-toolbar"><div className="search-field"><Icon name="search" size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search title, owner or tag…" /><kbd>⌘ K</kbd></div><div className="filter-group"><select value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Filter by status"><option value="all">All status</option><option value="ready">Ready</option><option value="processing">Processing</option><option value="review">Review due</option></select><select value={classification} onChange={(event) => setClassification(event.target.value)} aria-label="Filter by classification"><option value="all">All classifications</option><option>Public</option><option>Internal</option><option>Confidential</option><option>Restricted</option><option>Highly Restricted</option></select><button className="filter-button" onClick={() => onToast('Advanced knowledge filters opened')}><Icon name="sliders" size={15} /> Filters</button></div></div>{error && <ErrorNotice message={error} onRetry={load} />}{loading ? <LoadingBlock lines={6} /> : documents.length === 0 ? <EmptyState icon="database" title="No matching sources" description="Try a different search or upload the first source to this workspace." action={<Button icon="upload" onClick={() => setUploadOpen(true)}>Upload source</Button>} /> : <div className="document-table"><div className="table-row table-head"><span>Source</span><span>Classification</span><span>Owner</span><span>Last updated</span><span>Status</span><span /></div>{documents.map((document) => <button className="table-row document-row" key={document.id} onClick={() => setSelected(document)}><span className="document-name"><span className={`document-icon doc-${document.fileType.toLowerCase()}`}><Icon name={documentIcon(document.fileType)} size={17} /></span><span><strong>{document.title}</strong><small>{document.fileType} · {document.fileSize} · {document.version}</small></span></span><span><ClassificationBadge value={document.classification} /></span><span className="owner-cell"><Avatar initials={document.owner.split(' ').map((part) => part[0]).join('')} tone="slate" size="sm" /><span>{document.owner}</span></span><span className="updated-cell"><strong>{relativeTime(document.updatedAt)}</strong><small>{document.source}</small></span><span><DocumentStatus status={document.status} /></span><Icon name="chevron-right" size={15} className="row-chevron" /></button>)}</div>}</Panel>{selected && <DocumentDrawer document={selected} onClose={() => setSelected(null)} onToast={onToast} />}{uploadOpen && <UploadModal onClose={() => setUploadOpen(false)} onUploaded={(document) => { setDocuments((items) => [document, ...items]); setUploadOpen(false); onToast('Source queued for malware scan and indexing') }} />}</div>
}

function DocumentDrawer({ document, onClose, onToast }: { document: DocumentRecord; onClose: () => void; onToast: (message: string) => void }) { return <div className="modal-backdrop" onClick={onClose}><div className="side-modal document-drawer" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={onClose}><Icon name="x" size={18} /></button><div className={`document-icon doc-${document.fileType.toLowerCase()} drawer-icon`}><Icon name={documentIcon(document.fileType)} size={23} /></div><ClassificationBadge value={document.classification} /><h2>{document.title}</h2><p className="drawer-description">{document.source} · owned by {document.owner}</p><DocumentStatus status={document.status} /><div className="drawer-section"><span className="drawer-label">Source controls</span><div className="detail-list"><div><span>Version</span><strong>{document.version}</strong></div><div><span>AI trust</span><strong>{document.trust ? `${document.trust}/100` : 'Pending indexing'}</strong></div><div><span>Chunks indexed</span><strong>{document.chunks || 'Pending'}</strong></div><div><span>Next review</span><strong>{formatDate(document.nextReview)}</strong></div></div></div><div className="drawer-section"><span className="drawer-label">Tags</span><div className="tag-list">{document.tags.map((tag) => <span key={tag}><Icon name="tag" size={12} />{tag}</span>)}</div></div><div className="drawer-actions"><Button icon="file-check" onClick={() => onToast('Opening a permission-checked preview')}>Open preview</Button><Button variant="secondary" icon="refresh" onClick={() => onToast('Re-index job queued with an idempotency key')}>Re-index</Button></div></div></div> }

function UploadModal({ onClose, onUploaded }: { onClose: () => void; onUploaded: (document: DocumentRecord) => void }) { const [file, setFile] = useState<File | null>(null); const [title, setTitle] = useState(''); const [classification, setClassification] = useState('Internal'); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const choose = (event: ChangeEvent<HTMLInputElement>) => { const next = event.target.files?.[0] ?? null; setFile(next); if (next && !title) setTitle(next.name.replace(/\.[^.]+$/, '')) }; const submit = async (event: FormEvent) => { event.preventDefault(); if (!file) { setError('Choose a file to continue.'); return } setLoading(true); setError(''); try { const result = await api.uploadDocument(file, title || file.name, classification); onUploaded(result.document) } catch (caught) { setError(caught instanceof Error ? caught.message : 'Upload failed.') } finally { setLoading(false) } }; return <div className="modal-backdrop" onClick={onClose}><div className="modal-card upload-modal" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><div className="eyebrow">NEW KNOWLEDGE SOURCE</div><h2>Upload a trusted source</h2><p>Files are scanned, extracted, chunked and indexed asynchronously.</p></div><button className="modal-close inline" onClick={onClose}><Icon name="x" size={18} /></button></div><form onSubmit={submit}><label className="field-label">File<input type="file" accept=".pdf,.docx,.xlsx,.csv,.txt,.md,.html,.pptx" onChange={choose} /></label>{file ? <div className="selected-file"><span className="document-icon doc-pdf"><Icon name="file-check" size={17} /></span><span><strong>{file.name}</strong><small>{(file.size / 1024 / 1024).toFixed(2)} MB · security scan on upload</small></span><button type="button" onClick={() => setFile(null)}><Icon name="x" size={15} /></button></div> : <label className="dropzone"><input type="file" accept=".pdf,.docx,.xlsx,.csv,.txt,.md,.html,.pptx" onChange={choose} /><Icon name="upload" size={24} /><strong>Choose a document</strong><span>PDF, DOCX, XLSX, CSV, TXT, MD, HTML or PPTX · up to 25 MB</span></label>}<label className="field-label">Source title<input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="e.g. Information Security Policy" maxLength={240} /></label><label className="field-label">Classification<select value={classification} onChange={(event) => setClassification(event.target.value)}><option>Public</option><option>Internal</option><option>Confidential</option><option>Restricted</option><option>Highly Restricted</option></select></label>{error && <div className="inline-error"><Icon name="alert" size={15} />{error}</div>}<div className="upload-pipeline"><span><i className="pipeline-complete"><Icon name="shield-check" size={13} /></i> Security scan</span><Icon name="arrow-right" size={13} /><span><i><Icon name="file-text" size={13} /></i> Extract</span><Icon name="arrow-right" size={13} /><span><i><Icon name="sparkles" size={13} /></i> Index</span></div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit" icon="upload" disabled={loading}>{loading ? 'Uploading…' : 'Upload & queue'}</Button></div></form></div></div> }

export function Meetings({ onToast }: { onToast: (message: string) => void }) {
  const [meetings, setMeetings] = useState<MeetingRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [connected, setConnected] = useState(false)
  const [filter, setFilter] = useState('All meetings')
  useEffect(() => { api.meetings().then(({ items }) => setMeetings(items)).catch(() => undefined).finally(() => setLoading(false)) }, [])
  const filtered = meetings.filter((meeting) => filter === 'All meetings' || (filter === 'Needs review' ? meeting.status === 'Needs review' : filter === 'Summary ready' ? meeting.status === 'Summary ready' : true))
  return <div className="view-stack"><SectionHeading eyebrow="MEETING INTELLIGENCE" title="Turn conversation into momentum" description="Bring approved transcripts into the same evidence and action layer as your knowledge." action={<Button icon="calendar" onClick={() => onToast('Meeting connector setup opened')}>Connect calendar</Button>} /><div className="meeting-hero"><div className="meeting-hero-copy"><span className="meeting-orb"><Icon name="mic" size={21} /></span><div><h3>Meetings are a source of intelligence</h3><p>Connect Microsoft Teams, Zoom or Google Meet to process transcripts with tenant-scoped permissions.</p><button className="text-action" onClick={() => setConnected(true)}>{connected ? 'Connector pending admin consent' : 'Explore connectors'} <Icon name="arrow-right" size={15} /></button></div></div><div className="meeting-flow"><span><Icon name="mic" size={15} /> Transcript</span><Icon name="arrow-right" size={14} /><span><Icon name="sparkles" size={15} /> Summary</span><Icon name="arrow-right" size={14} /><span><Icon name="clipboard-check" size={15} /> Actions</span></div></div><Panel><div className="library-toolbar"><PanelTitle icon="calendar" title="Recent meetings" detail="Permission-aware transcripts and outputs" action={<div className="filter-group"><select value={filter} onChange={(event) => setFilter(event.target.value)}><option>All meetings</option><option>Needs review</option><option>Summary ready</option></select><button className="icon-button" onClick={() => onToast('Meeting filters opened')}><Icon name="sliders" size={16} /></button></div>} /></div>{loading ? <LoadingBlock lines={4} /> : filtered.length === 0 ? <EmptyState icon="calendar" title="No meetings in this view" description="Connect an approved meeting source or change the filter." /> : <div className="meeting-list">{filtered.map((meeting) => <button className="meeting-row" key={meeting.id} onClick={() => onToast(`Opening ${meeting.title} with participant access checks`)}><span className="meeting-date"><strong>{meeting.month}</strong><small>{meeting.day}</small></span><span className="meeting-copy"><strong>{meeting.title}</strong><small>{meeting.meta}</small></span><StatusBadge tone={meeting.tone}>{meeting.status}</StatusBadge><Icon name="chevron-right" size={16} /></button>)}</div>}</Panel><div className="meeting-capabilities"><div><Icon name="shield-check" size={18} /><strong>Permission first</strong><span>Transcript access follows meeting and tenant permissions.</span></div><div><Icon name="sparkles" size={18} /><strong>Source-grounded outputs</strong><span>Summaries preserve links back to approved transcript sections.</span></div><div><Icon name="workflow" size={18} /><strong>Action handoff</strong><span>Route decisions into durable workflows with approval gates.</span></div></div></div>
}

export function Agents({ onNavigate, onToast }: { onNavigate: (view: string, agentId?: string) => void; onToast: (message: string) => void }) { const [agents, setAgents] = useState<AgentRecord[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { api.agents().then(({ items }) => setAgents(items)).catch(() => undefined).finally(() => setLoading(false)) }, []); return <div className="view-stack"><SectionHeading eyebrow="AI AGENT REGISTRY" title="A governed network of experts" description="Configure, test and monitor agents that operate within your organization’s policies." action={<Button icon="plus" onClick={() => onToast('Agent creation requires a versioned configuration')}>Create agent</Button>} /><div className="agent-summary"><div><span className="summary-icon violet"><Icon name="bot" size={19} /></span><div><strong>{agents.length || '—'}</strong><span>Registered agents</span></div></div><div><span className="summary-icon teal"><Icon name="badge-check" size={19} /></span><div><strong>{agents.filter((agent) => agent.status === 'published').length || '—'}</strong><span>Published and governed</span></div></div><div><span className="summary-icon amber"><Icon name="activity" size={19} /></span><div><strong>{agents.length ? shortNumber(agents.reduce((sum, agent) => sum + agent.monthlyQueries, 0)) : '—'}</strong><span>Queries this month</span></div></div><div><span className="summary-icon blue"><Icon name="shield-check" size={19} /></span><div><strong>{agents.length ? `${Math.round(agents.reduce((sum, agent) => sum + agent.trust, 0) / agents.length)}` : '—'}</strong><span>Average trust</span></div></div></div>{loading ? <Panel><LoadingBlock lines={4} /></Panel> : <div className="agent-grid">{agents.map((agent) => <Panel className="agent-card" key={agent.id}><div className="agent-card-top"><span className={`agent-avatar agent-${agent.accent}`}>{agent.initials}</span><StatusBadge tone={agent.status === 'published' ? 'success' : agent.status === 'testing' ? 'warning' : 'neutral'}>{agent.status}</StatusBadge><button className="icon-button" onClick={() => onToast(`${agent.name} actions opened`)}><Icon name="more" size={16} /></button></div><h3>{agent.name}</h3><p>{agent.description}</p><div className="agent-owner"><Avatar initials={agent.owner.split(' ').map((part) => part[0]).join('')} size="sm" tone="slate" /><span>Owned by <strong>{agent.owner}</strong></span></div><div className="agent-stats"><span><strong>{agent.knowledgeSources}</strong> sources</span><span><strong>{agent.toolCount}</strong> tools</span><span><strong>{agent.trust}</strong> trust</span></div><div className="agent-card-foot"><span>{agent.version} · {agent.model.replace('Enterprise Reasoning · ', '')}</span><button onClick={() => onNavigate('ai-workspace', agent.id)}>Ask agent <Icon name="arrow-right" size={14} /></button></div></Panel>)}</div>}</div> }

export function Automations({ onToast }: { onToast: (message: string) => void }) { const [workflows, setWorkflows] = useState<WorkflowRecord[]>([]); const [loading, setLoading] = useState(true); const [running, setRunning] = useState<string | null>(null); useEffect(() => { api.workflows().then(({ items }) => setWorkflows(items)).catch(() => undefined).finally(() => setLoading(false)) }, []); const execute = async (workflow: WorkflowRecord) => { setRunning(workflow.id); try { const result = await api.executeWorkflow(workflow.id); onToast(`${workflow.name}: ${result.message}`) } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Could not start workflow') } finally { setRunning(null) } }; return <div className="view-stack"><SectionHeading eyebrow="AUTOMATIONS" title="Move from insight to action" description="Durable workflows with approvals, retries and a complete execution trail." action={<Button icon="plus" onClick={() => onToast('Workflow builder opened in draft mode')}>New workflow</Button>} /><div className="automation-banner"><div className="automation-banner-icon"><Icon name="workflow" size={23} /></div><div><strong>Workflow engine operational</strong><p>Executions continue in the worker service even when a browser session closes.</p></div><div className="engine-stats"><span><i className="online-dot" /> Queue healthy</span><span><strong>99.2%</strong> success rate</span></div></div>{loading ? <Panel><LoadingBlock lines={4} /></Panel> : <Panel><div className="workflow-table"><div className="table-row table-head"><span>Workflow</span><span>Trigger</span><span>Executions</span><span>Success</span><span>Last run</span><span /></div>{workflows.map((workflow) => <div className="table-row workflow-row" key={workflow.id}><span className="workflow-name"><span className="workflow-icon"><Icon name="workflow" size={17} /></span><span><strong>{workflow.name}</strong><small>{workflow.description}</small></span></span><span><span className="trigger-label"><Icon name={workflow.trigger.includes('Schedule') ? 'calendar' : workflow.trigger.includes('Security') ? 'shield-alert' : 'zap'} size={13} />{workflow.trigger}</span></span><span>{workflow.executions.toLocaleString()}</span><span className="success-rate">{workflow.successRate}%</span><span className="updated-cell"><strong>{workflow.lastRun}</strong><small>{workflow.requiresApproval ? 'Approval gate enabled' : 'Auto-run allowed'}</small></span><button className="run-button" disabled={workflow.status !== 'active' || running === workflow.id} onClick={() => void execute(workflow)}>{running === workflow.id ? <Icon name="refresh" size={15} className="spin" /> : <Icon name="play" size={14} />}</button></div>)}</div></Panel>}<div className="automation-foot"><Icon name="shield-check" size={16} /><span>All sensitive actions are evaluated against approval policies before execution.</span><button className="text-action" onClick={() => onToast('Opening approval policy controls')}>Review controls <Icon name="arrow-right" size={14} /></button></div></div> }

export function KnowledgeIntelligence({ overview, onNavigate }: { overview: DashboardOverview; onNavigate: (view: string) => void }) {
  const reviewItems = overview.risks.filter((risk) => risk.kind === 'conflict' || risk.kind === 'stale' || risk.kind === 'gap')
  const primaryConflict = overview.conflicts[0]
  const gapTone = (status: string): 'warning' | 'info' | 'neutral' => status === 'Open' ? 'warning' : status === 'Assigned' ? 'info' : 'neutral'
  return <div className="view-stack"><SectionHeading eyebrow="KNOWLEDGE INTELLIGENCE" title="Make knowledge healthier over time" description="Find gaps, resolve conflicts and keep every source ready for trusted retrieval." action={<Button icon="refresh" onClick={() => window.location.reload()}>Run health check</Button>} /><div className="intelligence-grid"><Panel className="intelligence-score"><PanelTitle icon="gauge" title="Health score" detail="Weighted across freshness, reliability, coverage and consistency" /><div className="intelligence-score-main"><HealthRing value={overview.organization.healthScore} /><div><strong>Strong foundation</strong><p>Knowledge is usable across most teams. Focus next on source freshness and unresolved conflicts.</p><button className="text-action" onClick={() => onNavigate('knowledge')}>Manage sources <Icon name="arrow-right" size={14} /></button></div></div><div className="intelligence-factor-grid">{overview.healthFactors.map((factor) => <div key={factor.label}><span>{factor.label}</span><ProgressBar value={factor.value} color={factor.tone === 'violet' ? '#8167e8' : factor.tone === 'teal' ? '#21b6a8' : factor.tone === 'amber' ? '#d99b42' : '#5f91d8'} /><strong>{factor.value}</strong></div>)}</div></Panel><Panel><PanelTitle icon="triangle-alert" title="Review queue" detail="Ranked by impact on answer quality" action={<StatusBadge tone="warning">{reviewItems.length} open</StatusBadge>} /><RiskList risks={reviewItems} /></Panel></div><div className="intelligence-lower"><Panel><PanelTitle icon="git-branch" title="Conflicts to resolve" detail="Contradictory sources are never silently merged" />{primaryConflict ? <div className="conflict-card"><span className="conflict-icon"><Icon name="git-branch" size={18} /></span><div><strong>{primaryConflict.title}</strong><p>{primaryConflict.description}</p><div className="conflict-versions">{primaryConflict.documents.map((document) => <span key={document.label}>{document.label} <b>{document.value}</b></span>)}</div></div><StatusBadge tone="danger">{primaryConflict.status}</StatusBadge></div> : <EmptyState icon="git-branch" title="No open conflicts" description="Conflicting source claims will appear here for owner review." />}</Panel><Panel><PanelTitle icon="help" title="Knowledge gaps" detail="Questions without strong evidence" action={<button className="panel-link" onClick={() => onNavigate('ai-workspace')}>Ask AI <Icon name="arrow-up-right" size={14} /></button>} />{overview.knowledgeGaps.length ? <div className="gap-list">{overview.knowledgeGaps.map((gap) => <div key={gap.id}><span className="gap-count">{String(gap.frequency).padStart(2, '0')}</span><span><strong>{gap.question}</strong><small>{gap.department} · asked {gap.frequency} times this month</small></span><StatusBadge tone={gapTone(gap.status)}>{gap.status}</StatusBadge></div>)}</div> : <EmptyState icon="help" title="No open gaps" description="Unanswered questions will be tracked here." />}</Panel></div></div>
}

function LineChart({ values, color = '#8167e8', suffix = '' }: { values: Array<{ label: string; value: number }>; color?: string; suffix?: string }) { const max = Math.max(...values.map((point) => point.value)); const min = Math.min(...values.map((point) => point.value)); const range = max - min || 1; const points = values.map((point, index) => `${(index / (values.length - 1)) * 100},${92 - ((point.value - min) / range) * 72}`).join(' '); return <div className="line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id={`chart-fill-${color.replace('#', '')}`} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={color} stopOpacity=".22" /><stop offset="1" stopColor={color} stopOpacity="0" /></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill={`url(#chart-fill-${color.replace('#', '')})`} /><polyline points={points} fill="none" stroke={color} strokeWidth="2.4" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />{values.map((point, index) => <circle key={point.label} cx={(index / (values.length - 1)) * 100} cy={92 - ((point.value - min) / range) * 72} r="1.8" fill="#fff" stroke={color} strokeWidth="1.5" vectorEffect="non-scaling-stroke" />)}</svg><div className="chart-labels">{values.map((point) => <span key={point.label}>{point.label.replace('Aug ', '').replace('Jul ', '')}</span>)}</div><div className="chart-end-label">{values[values.length - 1]?.value}{suffix}</div></div> }

export function Analytics({ onToast }: { onToast: (message: string) => void }) { const [data, setData] = useState<AnalyticsSnapshot | null>(null); const [loading, setLoading] = useState(true); const [tab, setTab] = useState('AI usage'); useEffect(() => { api.analytics().then(setData).catch(() => undefined).finally(() => setLoading(false)) }, []); if (loading) return <div className="view-stack"><SectionHeading eyebrow="ANALYTICS" title="Intelligence, measured" description="Usage and trust signals from real application events." /><Panel><LoadingBlock lines={5} /></Panel></div>; if (!data) return <EmptyState icon="bar-chart" title="Analytics are unavailable" description="The aggregation service did not return a snapshot." />; return <div className="view-stack"><SectionHeading eyebrow="ANALYTICS" title="Intelligence, measured" description="Usage, trust and cost signals from real application events." action={<div className="heading-actions"><button className="date-filter" onClick={() => onToast('Date range selector opened')}><Icon name="calendar" size={15} /> {data.period}<Icon name="chevron-down" size={14} /></button><Button icon="download" variant="secondary" onClick={() => onToast('Analytics export queued and will expire after 24 hours')}>Export report</Button></div>} /><div className="analytics-summary">{data.summary.map((item) => <div className="analytics-stat" key={item.label}><span className="analytics-stat-icon"><Icon name={item.icon} size={17} /></span><div><span>{item.label}</span><strong>{item.value}</strong><small className={item.trend >= 0 ? 'positive' : 'neutral'}>{item.trend >= 0 ? '+' : ''}{item.trend}% · {item.detail.replace(/^[-+]?\d+(\.\d+)?%?\s*/, '')}</small></div></div>)}</div><div className="analytics-grid"><Panel className="usage-chart-panel"><div className="chart-panel-head"><PanelTitle icon="activity" title="AI usage" detail="Queries per day" /><div className="chart-tabs">{['AI usage', 'Trust trend'].map((item) => <button className={tab === item ? 'active' : ''} onClick={() => setTab(item)} key={item}>{item}</button>)}</div></div>{tab === 'AI usage' ? <LineChart values={data.aiUsage} suffix="" /> : <LineChart values={data.trustTrend} color="#21b6a8" suffix="" />}</Panel><Panel className="department-chart-panel"><PanelTitle icon="bar-chart" title="Usage by department" detail="Share of AI queries" /><div className="donut-layout"><div className="donut-chart" style={{ background: `conic-gradient(${data.departmentUsage.map((item, index, all) => `${item.color} ${all.slice(0, index).reduce((sum, current) => sum + current.value, 0) / all.reduce((sum, current) => sum + current.value, 0) * 100}% ${(all.slice(0, index + 1).reduce((sum, current) => sum + current.value, 0) / all.reduce((sum, current) => sum + current.value, 0)) * 100}%`).join(', ')})` }}><div><strong>18.3k</strong><span>queries</span></div></div><div className="donut-legend">{data.departmentUsage.map((item) => <div key={item.label}><span style={{ background: item.color }} /><span>{item.label}</span><strong>{item.value}%</strong></div>)}</div></div></Panel></div><Panel><PanelTitle icon="circle-dollar-sign" title="Model usage & cost" detail="Transparent spend across approved providers" action={<StatusBadge tone="success">12% under budget</StatusBadge>} /><div className="model-table"><div className="table-row table-head"><span>Model route</span><span>Requests</span><span>Tokens</span><span>Estimated cost</span><span>Share</span></div>{data.modelUsage.map((model) => <div className="table-row" key={model.model}><span className="model-name"><span className="model-dot" /><strong>{model.model}</strong></span><span>{model.requests.toLocaleString()}</span><span>{model.tokens}</span><span className="cost-cell">{model.cost}</span><span className="share-cell"><ProgressBar value={model.share} color="#8167e8" /><b>{model.share}%</b></span></div>)}</div></Panel><Panel className="value-panel"><PanelTitle icon="badge-check" title="Business value" detail="Separate observed usage from estimates and unknowns" action={<StatusBadge tone="info">{data.valueMetrics.period}</StatusBadge>} /><div className="value-columns"><div><div className="value-column-title"><span className="value-column-dot measured" />Measured</div>{data.valueMetrics.measured.map((metric) => <div className="value-row" key={metric.key}><span><strong>{metric.label}</strong><small>{metric.detail}</small></span><b>{metric.value}</b></div>)}</div><div><div className="value-column-title"><span className="value-column-dot estimated" />Estimated</div>{data.valueMetrics.estimated.map((metric) => <div className="value-row" key={metric.key}><span><strong>{metric.label}</strong><small>{metric.detail}</small></span><b>{metric.value}</b></div>)}</div><div><div className="value-column-title"><span className="value-column-dot unknown" />Not measured</div>{data.valueMetrics.unavailable.map((metric) => <div className="value-row" key={metric.key}><span><strong>{metric.label}</strong><small>{metric.detail}</small></span><b>—</b></div>)}</div></div></Panel></div> }

export function ProductHealth({ onNavigate }: { onNavigate: (view: string) => void }) {
  const [data, setData] = useState<ProductHealthSnapshot | null>(null)
  const [alerts, setAlerts] = useState<ProactiveAlert[]>([])
  const [loading, setLoading] = useState(true)
  useEffect(() => { api.productHealth().then(setData).catch(() => undefined).finally(() => setLoading(false)); api.alerts().then(({ items }) => setAlerts(items)).catch(() => setAlerts([])) }, [])
  if (loading) return <div className="view-stack"><SectionHeading eyebrow="PRODUCT HEALTH" title="Would you trust this platform to run?" description="A stakeholder view of quality, safety, reliability and value." /><Panel><LoadingBlock lines={7} /></Panel></div>
  if (!data) return <EmptyState icon="activity" title="Product health is unavailable" description="The health service did not return a snapshot." />
  const kindTone = (kind: ProductHealthSnapshot['dimensions'][number]['kind']): 'success' | 'warning' | 'neutral' => kind === 'measured' ? 'success' : kind === 'estimated' ? 'warning' : 'neutral'
  const updateAlert = async (alertId: string, action: 'dismiss' | 'snooze') => { try { await api.updateAlert(alertId, action); setAlerts((current) => current.filter((alert) => alert.id !== alertId)) } catch { /* Keep the signal visible if the action was not persisted. */ } }
  return <div className="view-stack"><SectionHeading eyebrow="PRODUCT HEALTH" title="Would you trust this platform to run?" description="A stakeholder view of quality, safety, reliability and measurable value." action={<div className="heading-actions"><StatusBadge tone={data.status === 'healthy' ? 'success' : data.status === 'watch' ? 'warning' : 'neutral'}>{data.status.replace('_', ' ')}</StatusBadge><Button icon="badge-check" onClick={() => onNavigate('ai-evaluation')}>Open evaluation center</Button></div>} /><div className="product-health-hero"><div className="product-health-score"><div className="product-health-ring" style={{ '--health-score': `${(data.overall ?? 0) * 3.6}deg` } as CSSProperties}><div><strong>{data.overall ?? '—'}</strong>{data.overall !== null && <small>/100</small>}</div></div><div><span>PRODUCT HEALTH</span><strong>{data.overall === null ? 'Measurement in progress' : data.overall >= 85 ? 'Healthy with clear gaps' : 'Needs attention'}</strong><p>Only measured dimensions contribute to the overall score. Unknowns remain visible instead of being filled with assumptions.</p></div></div><div className="health-principles"><span><Icon name="shield-check" size={16} /> Trust is observable</span><span><Icon name="database" size={16} /> Data is permissioned</span><span><Icon name="workflow" size={16} /> Actions are governed</span><span><Icon name="bar-chart" size={16} /> Value is measured</span></div></div><Panel><PanelTitle icon="activity" title="Health dimensions" detail="Measured, estimated and unmeasured signals are intentionally distinguished" /><div className="health-dimension-grid">{data.dimensions.map((dimension) => <div className={`health-dimension health-${dimension.kind}`} key={dimension.key}><div className="health-dimension-head"><span>{dimension.label}</span><StatusBadge tone={kindTone(dimension.kind)}>{dimension.kind.replace('_', ' ')}</StatusBadge></div><div className="health-dimension-value">{dimension.value === null ? '—' : `${dimension.value}`}{dimension.value !== null && <small>/100</small>}</div>{dimension.value !== null && <ProgressBar value={dimension.value} color={dimension.kind === 'measured' ? '#21b6a8' : '#d99b42'} />}<p>{dimension.detail}</p></div>)}</div></Panel><div className="stakeholder-actions"><div><Icon name="users" size={17} /><span><strong>For employees</strong><small>Ask, verify and act from one workspace.</small></span><button onClick={() => onNavigate('ai-workspace')}>Open AI workspace <Icon name="arrow-right" size={13} /></button></div><div><Icon name="shield" size={17} /><span><strong>For security</strong><small>Review policies, identity and access boundaries.</small></span><button onClick={() => onNavigate('governance')}>Review controls <Icon name="arrow-right" size={13} /></button></div><div><Icon name="bar-chart" size={17} /><span><strong>For executives</strong><small>See adoption, cost and outcome evidence.</small></span><button onClick={() => onNavigate('analytics')}>View analytics <Icon name="arrow-right" size={13} /></button></div></div><Panel className="alert-management-panel"><PanelTitle icon="zap" title="Proactive signal inbox" detail="Low-noise alerts with an owner and next action" action={<StatusBadge tone={alerts.length ? 'warning' : 'success'}>{alerts.length ? `${alerts.length} open` : 'Clear'}</StatusBadge>} />{alerts.length ? <div className="alert-management-list">{alerts.map((alert) => <div className="alert-management-row" key={alert.id}><span className={`proactive-severity proactive-${alert.severity}`} /><span><strong>{alert.title}</strong><small>{alert.description}</small><em>Source: {alert.source}</em></span><button onClick={() => void updateAlert(alert.id, 'snooze')}>Snooze</button><button onClick={() => void updateAlert(alert.id, 'dismiss')}>Dismiss</button></div>)}</div> : <EmptyState icon="check-circle" title="No signals need attention" description="New evidence-backed deadlines, conflicts and approvals will appear here." />}</Panel></div>
}

export function ReadinessCenter({ onNavigate }: { onNavigate: (view: string) => void }) {
  const [data, setData] = useState<ReadinessSnapshot | null>(null)
  const [loading, setLoading] = useState(true)
  useEffect(() => { api.readiness().then(setData).catch(() => undefined).finally(() => setLoading(false)) }, [])
  if (loading) return <div className="view-stack"><SectionHeading eyebrow="LAUNCH READINESS" title="A clear path to safe launch" description="Validate identity, knowledge, AI, security and operations before enabling production use." /><Panel><LoadingBlock lines={8} /></Panel></div>
  if (!data) return <EmptyState icon="clipboard-check" title="Readiness is unavailable" description="The readiness service did not return a launch assessment." />
  const statusTone = (status: ReadinessSnapshot['checks'][number]['status']): 'success' | 'warning' | 'danger' => status === 'ready' ? 'success' : status === 'warning' ? 'warning' : 'danger'
  const openCheck = (id: string) => { const target: Record<string, string> = { knowledge: 'knowledge', policy: 'governance', model: 'ai-agents', security: 'governance', storage: 'administration', queue: 'administration', connectors: 'administration', agents: 'ai-agents', identity: 'administration' }; onNavigate(target[id] ?? 'administration') }
  const ready = data.checks.filter((check) => check.status === 'ready').length
  return <div className="view-stack"><SectionHeading eyebrow="LAUNCH READINESS" title="A clear path to safe launch" description={`Assessment for ${data.organizationName}. Validate the foundation before employees depend on it.`} action={<div className="heading-actions"><StatusBadge tone={data.status === 'READY' ? 'success' : data.status === 'READY_WITH_WARNINGS' ? 'warning' : 'danger'}>{data.status.replaceAll('_', ' ')}</StatusBadge><Button icon="refresh" onClick={() => window.location.reload()}>Re-run checks</Button></div>} /><div className={`readiness-banner readiness-${data.status.toLowerCase()}`}><span className="readiness-mark"><Icon name={data.status === 'READY' ? 'check' : data.status === 'NOT_READY' ? 'shield-alert' : 'triangle-alert'} size={23} /></span><div><strong>{data.status === 'READY' ? 'Ready for controlled launch' : data.status === 'READY_WITH_WARNINGS' ? 'Ready with explicit warnings' : 'Not ready for production'}</strong><p>{ready} of {data.checks.length} launch checks are ready. A warning is not hidden behind a green score.</p></div><div className="readiness-progress"><strong>{Math.round(ready / data.checks.length * 100)}%</strong><ProgressBar value={ready / data.checks.length * 100} color={data.status === 'NOT_READY' ? '#d4777e' : '#21b6a8'} /></div></div><div className="readiness-layout"><Panel><PanelTitle icon="clipboard-check" title="Launch checks" detail="Evidence-based gates across the stakeholder journey" /><div className="readiness-checks">{data.checks.map((check) => <button className="readiness-check" key={check.id} onClick={() => openCheck(check.id)}><span className={`readiness-check-icon check-${check.status}`}><Icon name={check.status === 'ready' ? 'check' : check.status === 'warning' ? 'triangle-alert' : 'shield-alert'} size={16} /></span><span className="readiness-check-copy"><strong>{check.label}</strong><small>{check.category} · {check.detail}</small></span><StatusBadge tone={statusTone(check.status)}>{check.status}</StatusBadge><Icon name="arrow-up-right" size={14} /></button>)}</div></Panel><Panel className="readiness-next"><PanelTitle icon="arrow-right" title="Before launch" detail="The next actions that remove the most risk" /><div className="next-step-list">{data.nextSteps.length ? data.nextSteps.map((step, index) => <div key={step}><span>{String(index + 1).padStart(2, '0')}</span><p>{step}</p></div>) : <EmptyState icon="check-circle" title="No open actions" description="The current readiness configuration has no outstanding steps." />}</div><div className="readiness-note"><Icon name="info" size={15} /><span>Readiness is a decision aid, not a certification. Production launch still requires tenant-specific security, load and recovery validation.</span></div></Panel></div></div>
}

export function AIEvaluation({ onToast }: { onToast: (message: string) => void }) {
  const [data, setData] = useState<EvaluationSnapshot | null>(null)
  const [loading, setLoading] = useState(true)
  const [running, setRunning] = useState(false)
  const [models, setModels] = useState<ModelProfile[]>([])
  const [scorecards, setScorecards] = useState<ModelScorecard[]>([])
  const load = () => { setLoading(true); api.evaluation().then(setData).catch(() => undefined).finally(() => setLoading(false)); api.models().then((catalog) => setModels(catalog.items)).catch(() => setModels([])); api.scorecards().then((catalog) => setScorecards(catalog.items)).catch(() => setScorecards([])) }
  useEffect(() => { load() }, [])
  const run = async () => { setRunning(true); try { const result = await api.runEvaluation(); setData(result); onToast(`Evaluation complete · ${result.passedCases}/${result.totalCases} cases passed`) } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Evaluation could not run') } finally { setRunning(false) } }
  if (loading) return <div className="view-stack"><SectionHeading eyebrow="AI EVALUATION CENTER" title="Measure intelligence before shipping" description="Golden cases test grounding, citations, routing, refusals and clarification behavior." /><Panel><LoadingBlock lines={6} /></Panel></div>
  if (!data) return <EmptyState icon="badge-check" title="Evaluation data is unavailable" description="The evaluation service did not return a snapshot. Check the API and try again." action={<Button icon="refresh" onClick={load}>Retry evaluation</Button>} />
  return <div className="view-stack"><SectionHeading eyebrow="AI EVALUATION CENTER" title="Measure intelligence before shipping" description="Golden cases test grounding, citations, routing, refusals and clarification behavior." action={<div className="heading-actions"><StatusBadge tone="info">{data.datasetVersion}</StatusBadge><Button icon="play" onClick={() => void run()} disabled={running}>{running ? 'Running…' : 'Run evaluation'}</Button></div>} /><div className="evaluation-hero"><div className="evaluation-score"><span>QUALITY SCORE</span><strong>{data.score}<small>/100</small></strong><ProgressBar value={data.score} color="#21b6a8" height={7} /><em>{data.passedCases} of {data.totalCases} golden cases passed</em></div><div className="evaluation-metrics"><div><span>Groundedness</span><strong>{data.groundedness}%</strong><small>Authorized evidence behavior</small></div><div><span>Citation coverage</span><strong>{data.citationCoverage}%</strong><small>Responses with sources</small></div><div><span>Refusal accuracy</span><strong>{data.refusalAccuracy}%</strong><small>Knows when not to answer</small></div><div><span>Avg. latency</span><strong>{data.averageLatencyMs}ms</strong><small>Development baseline</small></div></div></div><div className="evaluation-grid"><Panel><PanelTitle icon="bar-chart" title="Quality by category" detail="Failures are release signals, not hidden" /><div className="evaluation-categories">{data.categories.map((category) => <div key={category.label}><div><span>{category.label}</span><strong>{category.passed}/{category.total}</strong></div><ProgressBar value={category.score} color={category.score >= 80 ? '#21b6a8' : category.score >= 60 ? '#d99b42' : '#d4779a'} /><small>{category.score}% pass rate</small></div>)}</div></Panel><Panel><PanelTitle icon="shield-check" title="Evaluation contract" detail="What this suite protects" /><div className="evaluation-contract"><span><Icon name="check" size={14} /> Permission-aware retrieval</span><span><Icon name="check" size={14} /> Citation correctness</span><span><Icon name="check" size={14} /> Prompt-injection refusal</span><span><Icon name="check" size={14} /> Ambiguity clarification</span><span><Icon name="check" size={14} /> Route and response type</span></div><button className="panel-footer-link" onClick={() => onToast('Evaluation dataset editor opened')}>Manage golden dataset <Icon name="arrow-right" size={14} /></button></Panel></div><Panel><PanelTitle icon="network" title="Model route catalog" detail="Policy-selectable profiles; external quality is never guessed" action={<StatusBadge tone="neutral">{models.length} profiles</StatusBadge>} /><div className="model-route-list">{models.map((model) => <div className="model-route-row" key={model.id}><span className={`model-tier-dot tier-${model.tier}`} /><span className="model-route-name"><strong>{model.id}</strong><small>{model.provider} · {model.tier} · {model.contextWindow >= 1000000 ? `${(model.contextWindow / 1000000).toFixed(2)}M` : `${Math.round(model.contextWindow / 1000)}k`} context</small></span><span className="model-route-capabilities">{model.capabilities.filter((capability) => ['vision', 'tools', 'structured', 'web'].includes(capability)).join(' · ')}</span><span className="model-route-cost">{model.outputUsdPerMillion === null ? 'Provider price' : `$${model.outputUsdPerMillion}/M out`}</span><StatusBadge tone={scorecards.find((scorecard) => scorecard.modelId === model.id)?.status === 'measured' ? 'success' : 'warning'}>{scorecards.find((scorecard) => scorecard.modelId === model.id)?.status === 'measured' ? `${scorecards.find((scorecard) => scorecard.modelId === model.id)?.weightedScore}/100` : 'Not benchmarked'}</StatusBadge></div>)}</div></Panel><Panel className="retrieval-quality-panel"><PanelTitle icon="search" title="Retrieval quality" detail="Measured against expected source IDs in the golden set" action={<StatusBadge tone="success">RAG checks</StatusBadge>} /><div className="retrieval-metrics"><div><span>Recall@5</span><strong>{Math.round(data.retrievalMetrics.recallAt5 * 100)}%</strong><small>Relevant sources found</small></div><div><span>Precision@5</span><strong>{Math.round(data.retrievalMetrics.precisionAt5 * 100)}%</strong><small>Candidate relevance</small></div><div><span>MRR</span><strong>{data.retrievalMetrics.mrr.toFixed(2)}</strong><small>First relevant rank</small></div><div><span>nDCG@5</span><strong>{data.retrievalMetrics.ndcgAt5.toFixed(2)}</strong><small>Rank quality</small></div></div></Panel><Panel><PanelTitle icon="list" title="Latest case results" detail={`Completed ${relativeTime(data.completedAt)}`} action={<button className="icon-button" onClick={load}><Icon name="refresh" size={16} /></button>} /><div className="evaluation-table"><div className="table-row table-head"><span>Case</span><span>Category</span><span>Intent</span><span>Evidence</span><span>Result</span></div>{data.cases.map((testCase) => <div className="table-row evaluation-row" key={testCase.id}><span><strong>{testCase.id.replaceAll('-', ' ')}</strong><small>{testCase.difficulty}</small></span><span>{testCase.category}</span><span className="mono-label">{testCase.intent}</span><span>{testCase.citationCount ? `${testCase.citationCount} citation${testCase.citationCount === 1 ? '' : 's'}` : 'No source'}</span><span><StatusBadge tone={testCase.passed ? 'success' : 'danger'}>{testCase.passed ? 'Passed' : 'Failed'}</StatusBadge></span></div>)}</div></Panel></div>
}

export function History({ onToast }: { onToast: (message: string) => void }) { const [items, setItems] = useState<AuditEvent[]>([]); const [loading, setLoading] = useState(true); const [filter, setFilter] = useState('All events'); useEffect(() => { api.history().then(({ items: next }) => setItems(next)).catch(() => undefined).finally(() => setLoading(false)) }, []); const filtered = items.filter((item) => filter === 'All events' || (filter === 'Security' ? item.eventType.includes('PERMISSION') || item.eventType.includes('LOGIN') : filter === 'AI' ? item.eventType.includes('AI') : item.eventType.includes(filter.toUpperCase()))); return <div className="view-stack"><SectionHeading eyebrow="HISTORY & AUDIT" title="A record you can trust" description="Searchable, tenant-scoped events across AI, knowledge, workflows and administration." action={<div className="heading-actions"><div className="search-field compact"><Icon name="search" size={16} /><input placeholder="Search events…" /></div><Button icon="download" variant="secondary" onClick={() => onToast('Audit export queued with classification checks')}>Export log</Button></div>} /><Panel><div className="history-toolbar"><div className="segmented-tabs">{['All events', 'AI', 'Document', 'Workflow', 'Security'].map((item) => <button className={filter === item ? 'active' : ''} onClick={() => setFilter(item)} key={item}>{item}</button>)}</div><span className="retention-note"><Icon name="lock" size={14} /> Append-only audit trail</span></div>{loading ? <LoadingBlock lines={6} /> : <div className="history-table"><div className="table-row table-head"><span>Event</span><span>Actor</span><span>Resource</span><span>Outcome</span><span>Time</span></div>{filtered.map((item) => <div className="table-row history-row" key={item.id}><span className="history-event"><span className={`history-event-icon history-${item.severity}`}><Icon name={item.eventType.includes('AI') ? 'sparkles' : item.eventType.includes('DOCUMENT') ? 'file-text' : item.eventType.includes('WORKFLOW') || item.eventType.includes('APPROVAL') ? 'workflow' : 'shield-check'} size={15} /></span><span><strong>{item.eventType.replaceAll('_', ' ')}</strong><small>{item.description}</small></span></span><span className="owner-cell"><Avatar initials={item.actor.split(' ').map((part) => part[0]).join('')} size="sm" tone="slate" /><span>{item.actor}</span></span><span className="resource-cell">{item.resource}</span><span><StatusBadge tone={item.outcome === 'blocked' ? 'danger' : item.outcome === 'pending' ? 'warning' : 'success'}>{item.outcome}</StatusBadge></span><span className="time-cell">{relativeTime(item.timestamp)}</span></div>)}</div>}</Panel></div> }

export function Governance({ onToast }: { onToast: (message: string) => void }) { const [policies, setPolicies] = useState<PolicyRecord[]>([]); const [loading, setLoading] = useState(true); const [category, setCategory] = useState('All policies'); useEffect(() => { api.policies().then(({ items }) => setPolicies(items)).catch(() => undefined).finally(() => setLoading(false)) }, []); const filtered = policies.filter((policy) => category === 'All policies' || policy.category === category); return <div className="view-stack"><SectionHeading eyebrow="GOVERNANCE" title="Guardrails for responsible intelligence" description="Set model, data, approval and retention policy from one control plane." action={<Button icon="plus" onClick={() => onToast('Policy editor opened in draft mode')}>New policy</Button>} /><div className="governance-banner"><div className="governance-shield"><Icon name="shield-check" size={24} /></div><div><strong>Policy engine enforcing</strong><p>Every retrieval, model route and sensitive action is checked against the active tenant policy.</p></div><div className="governance-banner-stat"><strong>{policies.filter((policy) => policy.status === 'enforced').length || '—'}</strong><span>active controls</span></div><div className="governance-banner-stat"><strong>100%</strong><span>policy coverage</span></div></div><div className="policy-layout"><Panel><div className="policy-toolbar"><div className="segmented-tabs">{['All policies', 'AI policy', 'Data policy', 'Approval', 'Retention', 'Security'].map((item) => <button className={category === item ? 'active' : ''} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div><button className="icon-button" onClick={() => onToast('Policy filters opened')}><Icon name="sliders" size={16} /></button></div>{loading ? <LoadingBlock lines={5} /> : <div className="policy-list">{filtered.map((policy) => <button className="policy-row" key={policy.id} onClick={() => onToast(`${policy.name} configuration opened`)}><span className={`policy-icon policy-${policy.category.toLowerCase().replace(' ', '-')}`}><Icon name={policy.category === 'AI policy' ? 'sparkles' : policy.category === 'Approval' ? 'clipboard-check' : policy.category === 'Retention' ? 'clock' : policy.category === 'Security' ? 'shield' : 'database'} size={16} /></span><span className="policy-copy"><strong>{policy.name}</strong><small>{policy.description}</small><em>{policy.scope} · owned by {policy.owner}</em></span><StatusBadge tone={policy.status === 'enforced' ? 'success' : policy.status === 'review' ? 'warning' : 'neutral'}>{policy.status}</StatusBadge><Icon name="chevron-right" size={15} /></button>)}</div>}</Panel><Panel className="control-panel"><PanelTitle icon="sliders" title="Control posture" detail="Current organization configuration" /><div className="control-item"><span className="control-item-icon teal"><Icon name="sparkles" size={16} /></span><div><strong>Citations required</strong><small>AI answers must include permissioned evidence.</small></div><span className="toggle on"><i /></span></div><div className="control-item"><span className="control-item-icon violet"><Icon name="lock" size={16} /></span><div><strong>Restricted model boundary</strong><small>Sensitive sources route only to approved models.</small></div><span className="toggle on"><i /></span></div><div className="control-item"><span className="control-item-icon amber"><Icon name="clipboard-check" size={16} /></span><div><strong>Human approval gates</strong><small>Access, financial and external actions pause for review.</small></div><span className="toggle on"><i /></span></div><div className="control-item"><span className="control-item-icon blue"><Icon name="download" size={16} /></span><div><strong>Expiring exports</strong><small>Downloads expire after 24 hours and are audited.</small></div><span className="toggle on"><i /></span></div><button className="panel-footer-link" onClick={() => onToast('Policy simulator opened with a dry-run evaluation')}>Open policy simulator <Icon name="arrow-right" size={14} /></button></Panel></div></div> }

export function Administration({ onToast }: { onToast: (message: string) => void }) { const [users, setUsers] = useState<AdminUser[]>([]); const [loading, setLoading] = useState(true); const [tab, setTab] = useState('Users'); useEffect(() => { api.users().then(({ items }) => setUsers(items)).catch(() => undefined).finally(() => setLoading(false)) }, []); return <div className="view-stack"><SectionHeading eyebrow="ADMINISTRATION" title="People, access and integrations" description="Manage identity, roles and enterprise connections without losing the audit trail." action={<Button icon="user" onClick={() => onToast('Invite flow opened with role and department controls')}>Invite user</Button>} /><div className="admin-tabs">{['Users', 'Groups', 'Roles & permissions', 'SSO & SCIM', 'Integrations'].map((item) => <button className={tab === item ? 'active' : ''} onClick={() => setTab(item)} key={item}><Icon name={item === 'Users' ? 'users' : item === 'Groups' ? 'network' : item === 'Roles & permissions' ? 'key' : item === 'SSO & SCIM' ? 'lock' : 'link'} size={16} />{item}</button>)}</div>{tab === 'Users' ? <Panel><div className="library-toolbar"><PanelTitle icon="users" title="Organization members" detail={`${users.length || '—'} visible identities · tenant-scoped`} action={<div className="filter-group"><div className="search-field compact"><Icon name="search" size={15} /><input placeholder="Search members…" /></div><button className="filter-button" onClick={() => onToast('Member filters opened')}><Icon name="sliders" size={15} /> Filter</button></div>} /></div>{loading ? <LoadingBlock lines={6} /> : <div className="users-table"><div className="table-row table-head"><span>Member</span><span>Department</span><span>Role</span><span>Last active</span><span>Risk</span><span>Status</span></div>{users.map((user) => <div className="table-row user-row" key={user.id}><span className="member-cell"><Avatar initials={user.initials} tone={user.risk === 'medium' ? 'amber' : 'slate'} /><span><strong>{user.name}</strong><small>{user.email}</small></span></span><span>{user.department}</span><span>{user.role}</span><span>{user.lastActive}</span><span><StatusBadge tone={user.risk === 'low' ? 'success' : user.risk === 'medium' ? 'warning' : 'danger'}>{user.risk} risk</StatusBadge></span><span><StatusBadge tone={user.status === 'active' ? 'success' : 'neutral'}>{user.status}</StatusBadge></span></div>)}</div>}</Panel> : <AdminPlaceholder tab={tab} onToast={onToast} />}</div> }
function AdminPlaceholder({ tab, onToast }: { tab: string; onToast: (message: string) => void }) {
  const section = tab === 'Groups' ? 'groups' : tab === 'Roles & permissions' ? 'roles' : tab === 'SSO & SCIM' ? 'sso' : 'integrations'
  const [items, setItems] = useState<AdminConfigurationRecord[]>([])
  const [loading, setLoading] = useState(true)
  useEffect(() => { setLoading(true); api.adminConfiguration(section).then(({ items: next }) => setItems(next)).catch(() => setItems([])).finally(() => setLoading(false)) }, [section])
  return <Panel className="admin-placeholder"><div className="placeholder-icon"><Icon name={tab === 'Integrations' ? 'link' : 'lock'} size={22} /></div><h3>{tab}</h3><p>Configuration is controlled by tenant administrators and protected by audit events.</p>{loading ? <LoadingBlock lines={3} /> : <div className="placeholder-list">{items.map((item) => <button key={item.id} onClick={() => onToast(`${item.title} configuration opened`)}><span><strong>{item.title}</strong><small>{item.detail}</small></span>{item.status ? <StatusBadge tone={item.status === 'Healthy' || item.status === 'Connected' || item.status === 'Verified' ? 'success' : item.status === 'Pending' ? 'warning' : 'info'}>{item.status}</StatusBadge> : <Icon name="chevron-right" size={16} />}</button>)}</div>}<Button icon="settings" variant="secondary" onClick={() => onToast(`Opening ${tab} configuration`)}>Manage {tab.toLowerCase()}</Button></Panel>
}

export function Settings({ user, onToast }: { user: SessionUser; onToast: (message: string) => void }) { const [mfa, setMfa] = useState(true); const [compact, setCompact] = useState(false); return <div className="view-stack settings-view"><SectionHeading eyebrow="SETTINGS" title="Your workspace, your way" description="Personal preferences are scoped to your identity. Organization controls stay with administrators." action={<StatusBadge tone="info">Changes saved automatically</StatusBadge>} /><div className="settings-layout"><Panel><PanelTitle icon="user" title="Profile" detail="Your identity and workspace context" /><div className="profile-card"><Avatar initials="MC" tone="violet" size="lg" /><div><h3>{user.displayName}</h3><p>{user.email}</p><span><Icon name="building" size={13} /> Operations · Northstar Holdings</span></div><Button variant="secondary" onClick={() => onToast('Profile editor opened')}>Edit profile</Button></div><div className="settings-fields"><label className="field-label">Display name<input defaultValue={user.displayName} /></label><label className="field-label">Timezone<select defaultValue="UTC"><option>UTC</option><option>America/New_York</option><option>Europe/London</option><option>Asia/Singapore</option></select></label></div></Panel><Panel><PanelTitle icon="shield" title="Security" detail="Session and authentication preferences" /><div className="setting-line"><div><strong>Multi-factor authentication</strong><small>Required for privileged access and export actions.</small></div><button className={`toggle ${mfa ? 'on' : ''}`} onClick={() => setMfa((value) => !value)} aria-label="Toggle multi-factor authentication"><i /></button></div><div className="setting-line"><div><strong>Active sessions</strong><small>1 browser session · last authenticated with OIDC and MFA.</small></div><button className="text-action" onClick={() => onToast('Session management opened')}>Manage <Icon name="arrow-right" size={14} /></button></div><div className="setting-line"><div><strong>API access</strong><small>Personal tokens are never exposed to the browser.</small></div><StatusBadge tone="success">Protected</StatusBadge></div></Panel><Panel><PanelTitle icon="sliders" title="Appearance" detail="Tune the workspace for your day" /><div className="setting-line"><div><strong>Compact data density</strong><small>Show more rows in libraries and audit views.</small></div><button className={`toggle ${compact ? 'on' : ''}`} onClick={() => setCompact((value) => !value)} aria-label="Toggle compact data density"><i /></button></div><div className="setting-line"><div><strong>AI response citations</strong><small>Keep evidence visible beside every answer.</small></div><StatusBadge tone="success">Always on</StatusBadge></div></Panel><Panel><PanelTitle icon="bell" title="Notifications" detail="Choose where governance signals reach you" /><div className="notification-choice"><span className="notification-choice-icon"><Icon name="mail" size={16} /></span><div><strong>Email digest</strong><small>Weekly knowledge health and policy summary</small></div><StatusBadge tone="info">Weekly</StatusBadge><Icon name="chevron-right" size={16} /></div><div className="notification-choice"><span className="notification-choice-icon"><Icon name="bell" size={16} /></span><div><strong>In-app alerts</strong><small>Approvals, failed jobs and access anomalies</small></div><StatusBadge tone="success">Enabled</StatusBadge><Icon name="chevron-right" size={16} /></div></Panel></div></div> }

const learningBadgeTone = (status: string): 'success' | 'warning' | 'danger' | 'info' | 'neutral' => {
  if (status === 'measured' || status === 'pass' || status === 'ready' || status === 'accepted') return 'success'
  if (status === 'synthetic' || status === 'estimated' || status === 'projected' || status === 'warning' || status === 'partial_fixture' || status === 'proposed') return 'warning'
  if (status === 'fail' || status === 'rejected') return 'danger'
  return 'neutral'
}

const learningValue = (item: ProductLearningSnapshot['qualityScores'][number]) => {
  if (item.value === null) return 'Not measured'
  if (item.unit === 'percent' || item.unit === 'score') return `${item.value}${item.unit === 'score' ? '/100' : '%'}`
  if (item.unit === 'milliseconds') return `${item.value} ms`
  if (item.unit === 'currency') return `$${item.value}`
  return item.value.toLocaleString()
}

function LearningMetricCard({ item }: { item: ProductLearningSnapshot['qualityScores'][number] }) {
  return <div className="learning-metric-card"><div className="learning-metric-top"><span className="learning-metric-icon"><Icon name={item.key.includes('security') ? 'shield-check' : item.key.includes('knowledge') || item.key.includes('rag') ? 'database' : item.key.includes('workflow') ? 'workflow' : item.key.includes('agent') ? 'bot' : 'activity'} size={16} /></span><StatusBadge tone={learningBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge></div><strong>{learningValue(item)}</strong><span>{item.label}</span><small>{item.detail}</small></div>
}

export function ProductLearning({ onToast }: { onToast: (message: string) => void }) {
  const [snapshot, setSnapshot] = useState<ProductLearningSnapshot | null>(null)
  const [loading, setLoading] = useState(true)
  const [running, setRunning] = useState(false)
  const [error, setError] = useState('')
  const load = () => { setLoading(true); setError(''); api.productLearning().then(setSnapshot).catch((caught) => setError(caught instanceof Error ? caught.message : 'Product learning data could not be loaded.')).finally(() => setLoading(false)) }
  useEffect(() => { load() }, [])
  if (loading && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 6 · PRODUCT LEARNING" title="Learning from enterprise usage" description="Loading measured signals, synthetic pilot fixtures and explicit evidence gaps." /><LoadingBlock lines={8} /></div>
  if (error && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 6 · PRODUCT LEARNING" title="Learning from enterprise usage" description="The learning dashboard stays separate from operational controls." /><ErrorNotice message={error} onRetry={load} /></div>
  if (!snapshot) return null
  const measuredFixture = snapshot.benchmark.qualityScore
  const syntheticPasses = snapshot.pilot.securityChecks.filter((check) => check.status === 'pass').length
  const topFailures = [...snapshot.failures].sort((left, right) => (right.syntheticPilotCount + right.observedCount) - (left.syntheticPilotCount + left.observedCount)).slice(0, 6)
  const onRunRegression = async () => { setRunning(true); try { await api.runEvaluation(); load(); onToast('Deterministic regression completed; benchmark catalog remains separate.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'The regression run failed.') } finally { setRunning(false) } }
  const reviewRecommendation = async (id: string, decision: 'accepted' | 'deferred' | 'rejected') => { try { await api.reviewRecommendation(id, decision); setSnapshot((current) => current ? { ...current, recommendations: current.recommendations.map((item) => item.id === id ? { ...item, status: decision } : item), nextPriorities: current.nextPriorities.map((item) => item.id === id ? { ...item, status: decision } : item) } : current); onToast(`Recommendation ${decision}. No production change was made.`) } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Recommendation review failed.') } }
  return <div className="view-stack product-learning-view">
    <SectionHeading eyebrow="PHASE 6 · PRODUCT LEARNING" title="From usage to better decisions" description="Observe, measure, test and improve without letting AI change production autonomously." action={<div className="heading-actions"><Button variant="quiet" icon="refresh" onClick={() => { if (window.confirm('Reset the synthetic pilot fixture? No production data will change.')) api.resetPilotEnvironment().then(() => { load(); onToast('Synthetic pilot fixture reset.') }).catch((caught) => onToast(caught instanceof Error ? caught.message : 'Pilot reset failed.')) }}>Reset fixture</Button><Button variant="secondary" icon="refresh" onClick={load}>Refresh signals</Button><Button icon="badge-check" onClick={() => void onRunRegression()} disabled={running}>{running ? 'Running fixture…' : 'Run fixture regression'}</Button></div>} />
    <div className="learning-notice"><span className="learning-notice-icon"><Icon name="info" size={17} /></span><div><strong>{snapshot.scope.environment}</strong><p>{snapshot.scope.notice}</p></div><StatusBadge tone="warning">{snapshot.scaleReadiness.classification}</StatusBadge></div>
    <div className="learning-loop"><div className="learning-loop-heading"><span className="eyebrow">OPERATING MODEL</span><strong>Continuous improvement loop</strong><small>Recommendations require evidence, owner review, evaluation and a controlled release.</small></div>{['Observe', 'Measure', 'Identify problem', 'Hypothesis', 'Evaluate', 'Approve', 'Monitor'].map((step, index) => <div className="learning-loop-step" key={step}><span>{String(index + 1).padStart(2, '0')}</span><strong>{step}</strong>{index < 6 && <Icon name="arrow-right" size={13} />}</div>)}</div>
    <div className="learning-summary-grid"><div className="learning-summary-card learning-summary-violet"><span><Icon name="badge-check" size={18} /></span><strong>{measuredFixture.value === null ? '—' : `${measuredFixture.value}/100`}</strong><small>Fixture regression quality</small><em>{measuredFixture.sampleSize ?? 0} deterministic cases · not customer evidence</em></div><div className="learning-summary-card learning-summary-teal"><span><Icon name="list" size={18} /></span><strong>{snapshot.benchmark.totalTasks}</strong><small>Benchmark tasks catalogued</small><em>{snapshot.benchmark.executedTasks} Phase 6 tasks executed · {snapshot.benchmark.notMeasuredTasks} not measured</em></div><div className="learning-summary-card learning-summary-amber"><span><Icon name="shield-check" size={18} /></span><strong>{syntheticPasses}/{snapshot.pilot.securityChecks.length}</strong><small>Synthetic permission checks</small><em>Staging RLS and connector ACL validation pending</em></div><div className="learning-summary-card learning-summary-rose"><span><Icon name="activity" size={18} /></span><strong>{snapshot.productHealth.overall === null ? 'Not measured' : `${snapshot.productHealth.overall}/100`}</strong><small>Evidence health</small><em>{snapshot.productHealth.detail}</em></div></div>
    <div className="learning-metric-grid">{snapshot.qualityScores.slice(0, 6).map((item) => <LearningMetricCard item={item} key={item.key} />)}</div>
    <Panel><PanelTitle icon="badge-check" title="Response quality rubric" detail="Each response is evaluated across ten dimensions; unavailable labels remain explicit." action={<StatusBadge tone="warning">Claim-level review pending</StatusBadge>} /><div className="learning-rubric-grid">{snapshot.qualityRubric.map((item) => <div key={item.key}><span><strong>{item.label}</strong><small>{item.provenance}</small></span><b>{learningValue(item)}</b><StatusBadge tone={learningBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge></div>)}</div></Panel>
    <div className="learning-grid learning-grid-wide"><Panel><PanelTitle icon="users" title="Controlled pilot environment" detail={`${snapshot.pilot.syntheticUserCount} synthetic users · ${snapshot.pilot.tenantCount} tenant fixtures · ${snapshot.pilot.knowledgeSources.length} source families · resettable`} action={<StatusBadge tone="warning">Synthetic only</StatusBadge>} /><div className="learning-pilot-head"><div><strong>{snapshot.pilot.departments.length}</strong><span>departments</span></div><div><strong>{snapshot.pilot.roles.length}</strong><span>role profiles</span></div><div><strong>{snapshot.pilot.dataset.materializedRecordCount}</strong><span>materialized records</span></div><div><strong>{snapshot.pilot.journeys.length}</strong><span>complete journeys</span></div></div><div className="learning-department-list">{snapshot.pilot.departments.map((department) => <div className="learning-department-row" key={department.id}><span className="learning-dept-avatar">{department.name.slice(0, 2).toUpperCase()}</span><span><strong>{department.name}</strong><small>{department.mission}</small></span><em>{department.syntheticUsers} users · {department.sourceCount} sources</em></div>)}</div></Panel><Panel><PanelTitle icon="shield" title="Permission matrix" detail="Positive and negative tests remain visible" /><div className="learning-check-list">{snapshot.pilot.securityChecks.map((check) => <div className="learning-check-row" key={check.id}><span className={`learning-check-icon learning-check-${check.status}`}><Icon name={check.status === 'pass' ? 'check' : 'alert'} size={13} /></span><span><strong>{check.scenario}</strong><small>Expected {check.expected} · observed {check.observed}</small></span><StatusBadge tone={learningBadgeTone(check.status)}>{check.status}</StatusBadge></div>)}</div><div className="learning-footnote"><Icon name="lock" size={13} /> {snapshot.pilot.syntheticNotice}</div></Panel></div>
    <div className="learning-grid learning-grid-wide"><Panel><PanelTitle icon="badge-check" title="Enterprise AI benchmark" detail={`${snapshot.benchmark.version} · permanent task catalog`} action={<StatusBadge tone={learningBadgeTone(snapshot.benchmark.regressionGate.status)}>{snapshot.benchmark.regressionGate.status.replaceAll('_', ' ')}</StatusBadge>} /><div className="benchmark-progress"><div><strong>{snapshot.benchmark.executedTasks}/{snapshot.benchmark.totalTasks}</strong><span>Phase 6 tasks executed</span></div><ProgressBar value={snapshot.benchmark.executedTasks / Math.max(1, snapshot.benchmark.totalTasks) * 100} color="#8167e8" /><small>{snapshot.benchmark.regressionGate.detail}</small></div><div className="learning-coverage-list">{snapshot.benchmark.categoryCoverage.slice(0, 8).map((item) => <div className="learning-coverage-row" key={item.category}><span>{item.category}</span><ProgressBar value={item.executedInPhase6 / Math.max(1, item.catalogued) * 100} color={item.status === 'not_run' ? '#d9dce5' : '#8167e8'} /><strong>{item.catalogued}</strong><StatusBadge tone={learningBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge></div>)}</div><div className="learning-footnote"><Icon name="info" size={13} /> The separate {measuredFixture.provenance} set is not substituted for the 120-task tenant-private benchmark.</div></Panel><Panel><PanelTitle icon="triangle-alert" title="Failure taxonomy" detail="Synthetic pilot signals versus observed events" action={<StatusBadge tone="warning">Classify every failure</StatusBadge>} /><div className="failure-list">{topFailures.map((failure) => <div className="failure-row" key={failure.category}><span className="failure-count">{failure.syntheticPilotCount + failure.observedCount}</span><span><strong>{failure.category}</strong><small>{failure.examples[0]}</small></span><em>{failure.developmentObservedCount ? `${failure.developmentObservedCount} dev` : '0 dev'} · {failure.productionObservedCount ? `${failure.productionObservedCount} production` : '0 production'}</em></div>)}</div><button className="panel-footer-link" onClick={() => onToast('Failure taxonomy is read-only until an owner reviews the evidence.')}>View all failure classes <Icon name="arrow-right" size={14} /></button></Panel></div>
    <div className="learning-grid"><Panel><PanelTitle icon="database" title="Knowledge intelligence" detail="Gaps, conflicts and freshness are improvement inputs" /><div className="learning-health-score"><HealthRing value={snapshot.knowledge.score.value ?? 0} /><div><strong>{snapshot.knowledge.gaps.length} gaps · {snapshot.knowledge.conflicts.length} conflicts</strong><small>{snapshot.knowledge.score.detail}</small></div></div><div className="learning-mini-list">{snapshot.knowledge.gaps.slice(0, 3).map((gap) => <div key={gap.id}><span className="learning-mini-dot learning-mini-amber" /><span><strong>{gap.question}</strong><small>{gap.frequency} asks · {gap.department} · owner {gap.suggestedOwner}</small></span><StatusBadge tone="warning">{gap.status}</StatusBadge></div>)}{snapshot.knowledge.conflicts.slice(0, 2).map((conflict) => <div key={conflict.id}><span className="learning-mini-dot learning-mini-rose" /><span><strong>{conflict.title}</strong><small>{conflict.authority}</small></span><StatusBadge tone="danger">Review</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="bot" title="Agent and workflow signals" detail="Invocations are not outcome success" /><div className="learning-agent-list">{snapshot.agents.rows.map((agent) => <div key={agent.id}><span className="learning-agent-avatar">{agent.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><span><strong>{agent.name}</strong><small>{agent.invocations?.toLocaleString() ?? '—'} invocations · success {agent.successRate ?? 'not measured'}</small></span><StatusBadge tone="warning">{snapshot.agents.status}</StatusBadge></div>)}</div><div className="learning-workflow-callout"><Icon name="workflow" size={15} /><span><strong>{snapshot.workflows.repeatedPatterns.length} repeated patterns detected</strong><small>{snapshot.workflows.repeatedPatterns[0]?.recommendation}</small></span></div></Panel></div>
    <div className="learning-grid learning-grid-wide"><Panel><PanelTitle icon="activity" title="Product health dimensions" detail="No greenwashing: missing dimensions stay unmeasured" /><div className="learning-health-table">{snapshot.productHealth.dimensions.map((dimension) => <div key={dimension.key}><span><strong>{dimension.label}</strong><small>{dimension.provenance}</small></span><span className="learning-health-value">{learningValue(dimension)}</span><StatusBadge tone={learningBadgeTone(dimension.status)}>{dimension.status.replaceAll('_', ' ')}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="bar-chart" title="Scale simulation" detail="Modeled, not load tested" action={<StatusBadge tone="warning">{snapshot.scale.status.replaceAll('_', ' ')}</StatusBadge>} /><div className="scale-table"><div className="scale-row scale-head"><span>Users</span><span>AI/day</span><span>Concurrent</span><span>Risk</span></div>{snapshot.scale.scenarios.map((scenario) => <div className="scale-row" key={scenario.users}><strong>{scenario.users.toLocaleString()}</strong><span>{scenario.aiRequestsPerDay.toLocaleString()}</span><span>{scenario.concurrentModelCalls}</span><StatusBadge tone={scenario.status === 'capacity_risk' ? 'danger' : 'warning'}>{scenario.status.replaceAll('_', ' ')}</StatusBadge></div>)}</div><div className="learning-footnote"><Icon name="info" size={13} /> {snapshot.scale.scenarios[3]?.bottlenecks.slice(0, 2).join(' · ')}</div></Panel></div>
    <div className="learning-grid learning-grid-wide"><Panel><PanelTitle icon="sparkles" title="Governed recommendations" detail="Evidence → owner → decision; no autonomous product changes" /><div className="recommendation-list">{snapshot.recommendations.map((recommendation) => <div className="recommendation-row" key={recommendation.id}><span className={`recommendation-priority recommendation-${recommendation.priority.toLowerCase()}`}>{recommendation.priority}</span><div><strong>{recommendation.title}</strong><small>{recommendation.reason}</small><em>{recommendation.suggestedOwner} · {Math.round(recommendation.confidence * 100)}% confidence · {recommendation.governance}</em></div><div className="recommendation-actions"><StatusBadge tone={learningBadgeTone(recommendation.status)}>{recommendation.status}</StatusBadge>{recommendation.status === 'proposed' && <><button onClick={() => void reviewRecommendation(recommendation.id, 'accepted')} aria-label={`Accept ${recommendation.title}`}><Icon name="check" size={14} /></button><button onClick={() => void reviewRecommendation(recommendation.id, 'deferred')} aria-label={`Defer ${recommendation.title}`}><Icon name="clock" size={14} /></button></>}</div></div>)}</div></Panel></div>
    <div className="learning-grid"><Panel><PanelTitle icon="flask" title="Controlled experiments" detail="Feature flags and rollback guardrails" /><div className="experiment-list">{snapshot.experiments.map((experiment) => <div key={experiment.id}><span className="experiment-icon"><Icon name="sparkles" size={15} /></span><span><strong>{experiment.key}</strong><small>{experiment.hypothesis}</small><em>{experiment.primaryMetric} · {experiment.variants.join(' vs ')}</em></span><StatusBadge tone={learningBadgeTone(experiment.status)}>{experiment.status}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="circle-dollar-sign" title="Cost and value evidence" detail="Activity is not ROI" /><div className="learning-value-list">{snapshot.businessValue.metrics.map((item) => <div key={item.key}><span><strong>{item.label}</strong><small>{item.detail}</small></span><strong>{item.value === null ? 'Not measured' : item.value.toLocaleString()} <small>{item.unit}</small></strong></div>)}</div><div className="learning-footnote"><Icon name="lock" size={13} /> {snapshot.cost.detail}</div></Panel></div>
    <div className="learning-grid learning-grid-wide"><Panel><PanelTitle icon="lightbulb" title="What the pilot is teaching us" detail="High-level signals for product, security and customer success" /><div className="learning-insight-columns"><div><span className="eyebrow">PAIN POINTS</span>{snapshot.topPainPoints.map((item) => <div className="learning-insight" key={item.title}><strong>{item.title}</strong><small>{item.detail}</small><em>{item.evidence}</em></div>)}</div><div><span className="eyebrow">NEXT OPPORTUNITIES</span>{snapshot.topOpportunities.map((item) => <div className="learning-insight" key={item.title}><strong>{item.title}</strong><small>{item.detail}</small><em>{item.evidence}</em></div>)}</div><div><span className="eyebrow">BLOCKING RISKS</span>{snapshot.topRisks.map((item) => <div className="learning-insight" key={item.title}><strong>{item.title}</strong><small>{item.detail}</small><em>{item.evidence}</em></div>)}</div></div></Panel></div>
    <div className="learning-graduation"><div><span className="learning-graduation-icon"><Icon name="clipboard-check" size={20} /></span><span><strong>Pilot success: {snapshot.pilotSuccess.status.replaceAll('_', ' ')}</strong><small>{snapshot.pilotSuccess.graduationRule}</small></span></div><StatusBadge tone="warning">{snapshot.scaleReadiness.classification}</StatusBadge></div>
  </div>
}

const operatingBadgeTone = (status: string): 'success' | 'warning' | 'danger' | 'info' | 'neutral' => {
  if (status === 'resolved' || status === 'acknowledged' || status === 'approved' || status === 'completed' || status === 'outcome_recorded') return 'success'
  if (status === 'open' || status === 'proposed' || status === 'action_pending' || status === 'important' || status === 'unusual') return 'warning'
  if (status === 'critical' || status === 'failed' || status === 'rejected') return 'danger'
  if (status === 'measured') return 'success'
  return 'neutral'
}

const operatingSeverityIcon = (severity: string) => severity === 'critical' ? 'shield-alert' : severity === 'high' ? 'triangle-alert' : severity === 'medium' ? 'clock' : 'info'

const splitLines = (value: string) => value.split('\n').map((item) => item.trim()).filter(Boolean)

export function OperatingIntelligence({ onToast }: { onToast: (message: string) => void }) {
  const [snapshot, setSnapshot] = useState<OperatingIntelligenceSnapshot | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [decisionOpen, setDecisionOpen] = useState(false)
  const [outcomeDecision, setOutcomeDecision] = useState<OperatingDecision | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [decisionForm, setDecisionForm] = useState({ title: '', context: '', evidence: '', alternatives: '', recommendation: '', risk: 'medium', classification: 'Internal' })
  const [outcomeForm, setOutcomeForm] = useState({ expected: '', actual: '', beforeValue: '', afterValue: '', status: 'expected' })
  const load = () => { setLoading(true); setError(''); api.operatingIntelligence().then(setSnapshot).catch((caught) => setError(caught instanceof Error ? caught.message : 'Operating intelligence could not be loaded.')).finally(() => setLoading(false)) }
  useEffect(() => { load() }, [])
  const openDecisionForSignal = (signal: OperatingIntelligenceSnapshot['signals'][number]) => { setDecisionForm({ title: signal.title, context: signal.summary, evidence: signal.evidence.join('\n'), alternatives: '', recommendation: signal.recommendedAction, risk: signal.severity, classification: signal.classification }); setDecisionOpen(true) }
  const createDecision = async (event: FormEvent) => { event.preventDefault(); setSubmitting(true); try { await api.createDecision({ title: decisionForm.title, context: decisionForm.context, evidence: splitLines(decisionForm.evidence), alternatives: splitLines(decisionForm.alternatives), recommendation: decisionForm.recommendation, risk: decisionForm.risk, classification: decisionForm.classification }); setDecisionOpen(false); load(); onToast('Decision record created. No action was executed.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Decision record could not be created.') } finally { setSubmitting(false) } }
  const approve = async (decision: OperatingDecision) => { try { await api.approveDecision(decision.id); load(); onToast('Decision approved. Choose an action only when ready.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Decision approval failed.') } }
  const act = async (decision: OperatingDecision) => { if (!window.confirm('Request the governed workflow action? Approval has already been recorded; downstream execution remains audited.')) return; try { await api.actOnDecision(decision.id, decision.action?.workflowId ?? decision.proposedWorkflowId ?? 'workflow-policy-review'); load(); onToast('Approved action requested and routed through the workflow boundary.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'The governed action could not be requested.') } }
  const openOutcome = (decision: OperatingDecision) => { setOutcomeDecision(decision); setOutcomeForm({ expected: decision.recommendation, actual: '', beforeValue: '', afterValue: '', status: 'expected' }) }
  const recordOutcome = async (event: FormEvent) => { event.preventDefault(); if (!outcomeDecision) return; setSubmitting(true); try { await api.recordOutcome({ decisionId: outcomeDecision.id, expected: outcomeForm.expected, actual: outcomeForm.actual, before: [{ key: 'tracked_metric', label: 'Tracked metric', value: outcomeForm.beforeValue ? Number(outcomeForm.beforeValue) : null, unit: 'value' }], after: [{ key: 'tracked_metric', label: 'Tracked metric', value: outcomeForm.afterValue ? Number(outcomeForm.afterValue) : null, unit: 'value' }], status: outcomeForm.status, evidence: ['Recorded through the governed operating-intelligence form'] }); setOutcomeDecision(null); load(); onToast('Outcome recorded in organizational memory.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Outcome could not be recorded.') } finally { setSubmitting(false) } }
  if (loading && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 8 · OPERATING INTELLIGENCE" title="Sense what matters" description="Loading signals, context, decisions, actions and outcomes." /><LoadingBlock lines={8} /></div>
  if (error && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 8 · OPERATING INTELLIGENCE" title="Sense what matters" description="Operating intelligence is isolated from the core employee experience." /><ErrorNotice message={error} onRetry={load} /></div>
  if (!snapshot) return null
  return <div className="view-stack operating-intelligence-view">
    <SectionHeading eyebrow="PHASE 8 · ENTERPRISE INTELLIGENCE OPERATING SYSTEM" title="Sense what matters" description="Turn authorized signals into explainable decisions, governed actions and measured outcomes." action={<div className="heading-actions"><Button variant="secondary" icon="refresh" onClick={load}>Refresh signals</Button><Button icon="clipboard-check" onClick={() => { setDecisionForm({ title: '', context: '', evidence: '', alternatives: '', recommendation: '', risk: 'medium', classification: 'Internal' }); setDecisionOpen(true) }}>Record decision</Button></div>} />
    <div className="operating-notice"><span className="operating-notice-icon"><Icon name="activity" size={17} /></span><div><strong>{snapshot.scope.environment}</strong><p>{snapshot.scope.notice}</p></div><StatusBadge tone="warning">Human oversight on</StatusBadge></div>
    <div className="operating-loop">{snapshot.operatingModel.stages.map((stage, index) => <div className="operating-loop-stage" key={stage}><span>{String(index + 1).padStart(2, '0')}</span><strong>{stage}</strong>{index < snapshot.operatingModel.stages.length - 1 && <Icon name="arrow-right" size={14} />}</div>)}</div>
    <div className="operating-metric-grid">{snapshot.metrics.map((item) => <div className="operating-metric" key={item.key}><span className="operating-metric-icon"><Icon name={item.key.includes('signal') ? 'activity' : item.key.includes('decision') ? 'clipboard-check' : item.key.includes('outcome') ? 'badge-check' : item.key.includes('process') ? 'workflow' : item.key.includes('memory') ? 'book' : 'sparkles'} size={16} /></span><strong>{item.value === null ? 'Not measured' : item.value.toLocaleString()}</strong><small>{item.label}</small><em>{item.detail}</em></div>)}</div>
    <div className="operating-grid operating-grid-wide"><Panel><PanelTitle icon="zap" title="Signals requiring attention" detail="Prioritized by impact, urgency, risk, confidence and affected scope" action={<StatusBadge tone="warning">{snapshot.signals.filter((signal) => signal.status === 'open').length} open</StatusBadge>} /><div className="operating-signal-list">{snapshot.signals.map((signal) => <div className="operating-signal-row" key={signal.id}><span className={`operating-signal-icon operating-signal-${signal.severity}`}><Icon name={operatingSeverityIcon(signal.severity)} size={15} /></span><div><strong>{signal.title}</strong><small>{signal.summary}</small><em>{signal.owner} · {signal.sourceMode} source · {Math.round(signal.confidence * 100)}% confidence</em></div><span className="operating-signal-score">{signal.priorityScore}<small>priority</small></span><StatusBadge tone={operatingBadgeTone(signal.state)}>{signal.state}</StatusBadge><button className="operating-row-action" onClick={() => openDecisionForSignal(signal)}>Decide <Icon name="arrow-right" size={13} /></button></div>)}</div></Panel><Panel><PanelTitle icon="clipboard-check" title="Decision queue" detail="AI recommends · an authorized human decides" action={<StatusBadge tone="info">{snapshot.decisions.length} records</StatusBadge>} /><div className="operating-decision-list">{snapshot.decisions.map((decision) => <div className="operating-decision-row" key={decision.id}><div><strong>{decision.title}</strong><small>{decision.context}</small><em>{decision.owner} · {decision.risk} risk · {decision.provenance}</em></div><StatusBadge tone={operatingBadgeTone(decision.status)}>{decision.status.replaceAll('_', ' ')}</StatusBadge><div className="operating-decision-actions">{decision.status === 'proposed' && <button onClick={() => void approve(decision)}>Approve</button>}{decision.status === 'approved' && <button onClick={() => void act(decision)}>Act safely</button>}{(decision.status === 'approved' || decision.status === 'action_pending' || decision.status === 'completed') && <button onClick={() => openOutcome(decision)}>Record outcome</button>}</div></div>)}{!snapshot.decisions.length && <EmptyState icon="clipboard-check" title="No decisions recorded" description="Create a decision from a prioritized signal when a human review is needed." />}</div></Panel></div>
    <div className="operating-grid operating-grid-wide"><Panel><PanelTitle icon="search" title="Context before action" detail="Relevant evidence, live state, relationships and unknowns" /><div className="operating-context-list">{snapshot.contexts.map((context) => <div key={context.id}><span className="operating-context-number"><Icon name="search" size={13} /></span><div><strong>{context.task}</strong><small>{context.subjectScope} · {context.sourceMode}</small><em>{context.selectedEvidence.slice(0, 2).join(' · ')}</em>{context.unknowns.length > 0 && <b>Unknown: {context.unknowns[0]}</b>}</div></div>)}</div></Panel><Panel><PanelTitle icon="workflow" title="Process intelligence" detail="Cycle time, wait, rework and manual bottlenecks" action={<StatusBadge tone="warning">{snapshot.processes.length} processes</StatusBadge>} /><div className="operating-process-list">{snapshot.processes.map((process) => <div key={process.id}><div className="operating-process-heading"><span><strong>{process.name}</strong><small>{process.department} · owner {process.owner}</small></span><StatusBadge tone={operatingBadgeTone(process.provenance)}>{process.provenance}</StatusBadge></div><div className="operating-process-metrics"><span>Cycle<strong>{process.cycleTimeHours === null ? '—' : `${process.cycleTimeHours}h`}</strong></span><span>Wait<strong>{process.waitTimeHours === null ? '—' : `${process.waitTimeHours}h`}</strong></span><span>Manual<strong>{process.manualSteps ?? '—'}</strong></span><span>Auto<strong>{process.automationRate === null ? '—' : `${Math.round(process.automationRate * 100)}%`}</strong></span></div><small className="operating-process-bottleneck">{process.bottleneck}</small></div>)}</div></Panel></div>
    <div className="operating-grid"><Panel><PanelTitle icon="shield-alert" title="Risk intelligence" detail="Evidence-backed risk, not an autonomous decision" /><div className="operating-insight-list">{snapshot.risks.map((risk) => <div key={risk.id}><span className={`operating-insight-dot operating-insight-${risk.severity}`} /><span><strong>{risk.title}</strong><small>{risk.summary}</small><em>{risk.evidence[0]} · owner {risk.owner}</em></span><StatusBadge tone={operatingBadgeTone(risk.severity)}>{risk.severity}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="sparkles" title="Opportunity intelligence" detail="Repeated work and process improvement candidates" /><div className="operating-insight-list">{snapshot.opportunities.map((opportunity) => <div key={opportunity.id}><span className="operating-insight-dot operating-insight-low" /><span><strong>{opportunity.title}</strong><small>{opportunity.summary}</small><em>{opportunity.evidence[0]} · {Math.round(opportunity.confidence * 100)}% confidence</em></span><StatusBadge tone="info">Review</StatusBadge></div>)}</div></Panel></div>
    <div className="operating-grid operating-grid-wide"><Panel><PanelTitle icon="book" title="Organizational memory" detail="Explicit decisions, lessons and outcomes with owner and retention" /><div className="operating-memory-list">{snapshot.memory.map((item) => <div key={item.id}><span className="operating-memory-icon"><Icon name={item.memoryType === 'outcome' ? 'badge-check' : item.memoryType === 'decision' ? 'clipboard-check' : 'book'} size={14} /></span><span><strong>{item.title}</strong><small>{item.summary}</small><em>{item.owner} · {item.authority} · {item.retention}</em></span><StatusBadge tone={operatingBadgeTone(item.status)}>{item.status}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="badge-check" title="Outcome learning" detail="Before, after, expected and actual remain separate" action={<StatusBadge tone={snapshot.outcomes.some((outcome) => outcome.status === 'measured') ? 'success' : 'warning'}>{snapshot.outcomes.length} tracked</StatusBadge>} /><div className="operating-outcome-list">{snapshot.outcomes.map((outcome) => <div key={outcome.id}><span><strong>{outcome.actual}</strong><small>{outcome.before[0]?.label ?? 'Metric'}: {outcome.before[0]?.value ?? '—'} → {outcome.after[0]?.value ?? '—'}</small><em>{outcome.provenance} · {outcome.measuredAt.slice(0, 10)}</em></span><StatusBadge tone={operatingBadgeTone(outcome.status)}>{outcome.status.replaceAll('_', ' ')}</StatusBadge></div>)}{!snapshot.outcomes.length && <EmptyState icon="badge-check" title="No outcomes measured" description="Record an approved decision outcome after the action is verified." />}</div></Panel></div>
    <div className="operating-reliability"><Icon name="shield-check" size={16} /><span><strong>Core product remains available if intelligence processing fails.</strong><small>{snapshot.reliability.detail}</small></span><StatusBadge tone="success">Isolation enabled</StatusBadge></div>
    {decisionOpen && <div className="modal-backdrop" onClick={() => setDecisionOpen(false)}><div className="modal-card operating-modal" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><div className="eyebrow">DECISION RECORD</div><h2>Make the decision explicit</h2><p>Capture context, evidence, alternatives and recommendation before any action.</p></div><button className="modal-close inline" onClick={() => setDecisionOpen(false)}><Icon name="x" size={18} /></button></div><form onSubmit={createDecision}><label className="field-label">Decision title<input required value={decisionForm.title} onChange={(event) => setDecisionForm({ ...decisionForm, title: event.target.value })} maxLength={240} /></label><label className="field-label">Context<textarea required value={decisionForm.context} onChange={(event) => setDecisionForm({ ...decisionForm, context: event.target.value })} maxLength={2000} /></label><label className="field-label">Evidence <small>one item per line</small><textarea required value={decisionForm.evidence} onChange={(event) => setDecisionForm({ ...decisionForm, evidence: event.target.value })} maxLength={4000} /></label><div className="operating-form-grid"><label className="field-label">Risk<select value={decisionForm.risk} onChange={(event) => setDecisionForm({ ...decisionForm, risk: event.target.value })}><option>low</option><option>medium</option><option>high</option><option>critical</option></select></label><label className="field-label">Classification<select value={decisionForm.classification} onChange={(event) => setDecisionForm({ ...decisionForm, classification: event.target.value })}><option>Public</option><option>Internal</option><option>Confidential</option><option>Restricted</option></select></label></div><label className="field-label">Alternatives <small>one item per line</small><textarea value={decisionForm.alternatives} onChange={(event) => setDecisionForm({ ...decisionForm, alternatives: event.target.value })} maxLength={3000} /></label><label className="field-label">Recommendation<textarea required value={decisionForm.recommendation} onChange={(event) => setDecisionForm({ ...decisionForm, recommendation: event.target.value })} maxLength={1200} /></label><div className="modal-actions"><Button variant="secondary" onClick={() => setDecisionOpen(false)}>Cancel</Button><Button type="submit" icon="clipboard-check" disabled={submitting}>{submitting ? 'Recording…' : 'Record decision'}</Button></div></form></div></div>}
    {outcomeDecision && <div className="modal-backdrop" onClick={() => setOutcomeDecision(null)}><div className="modal-card operating-modal" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><div className="eyebrow">OUTCOME RECORD</div><h2>Measure what happened</h2><p>{outcomeDecision.title}</p></div><button className="modal-close inline" onClick={() => setOutcomeDecision(null)}><Icon name="x" size={18} /></button></div><form onSubmit={recordOutcome}><label className="field-label">Expected outcome<textarea required value={outcomeForm.expected} onChange={(event) => setOutcomeForm({ ...outcomeForm, expected: event.target.value })} maxLength={1200} /></label><label className="field-label">Actual outcome<textarea required value={outcomeForm.actual} onChange={(event) => setOutcomeForm({ ...outcomeForm, actual: event.target.value })} maxLength={1200} /></label><div className="operating-form-grid"><label className="field-label">Before value<input type="number" value={outcomeForm.beforeValue} onChange={(event) => setOutcomeForm({ ...outcomeForm, beforeValue: event.target.value })} /></label><label className="field-label">After value<input type="number" value={outcomeForm.afterValue} onChange={(event) => setOutcomeForm({ ...outcomeForm, afterValue: event.target.value })} /></label></div><label className="field-label">Evidence status<select value={outcomeForm.status} onChange={(event) => setOutcomeForm({ ...outcomeForm, status: event.target.value })}><option value="expected">Expected only</option><option value="measured">Measured</option><option value="not_measured">Not measured</option><option value="failed">Failed</option></select></label><div className="modal-actions"><Button variant="secondary" onClick={() => setOutcomeDecision(null)}>Cancel</Button><Button type="submit" icon="badge-check" disabled={submitting}>{submitting ? 'Saving…' : 'Record outcome'}</Button></div></form></div></div>}
  </div>
}

const valueBadgeTone = (status: string): 'success' | 'warning' | 'danger' | 'info' | 'neutral' => {
  if (status === 'measured' || status === 'DIRECT' || status === 'HIGH') return 'success'
  if (status === 'estimated' || status === 'projected' || status === 'MEDIUM' || status === 'EXPERIMENT' || status === 'INVEST_SELECTIVELY') return 'warning'
  if (status === 'failed' || status === 'LOW') return 'danger'
  if (status === 'INVEST_HEAVILY') return 'info'
  return 'neutral'
}

const valueMetricText = (item: ValueIntelligenceSnapshot['summary'][number]) => {
  if (item.value === null) return 'Not measured'
  if (item.unit === 'USD') return `$${item.value.toLocaleString()}`
  if (item.unit === 'percent') return `${item.value}%`
  if (item.unit === 'score') return `${item.value}/100`
  return `${item.value.toLocaleString()} ${item.unit}`
}

function ValueMetricCard({ item }: { item: ValueIntelligenceSnapshot['summary'][number] }) {
  return <div className="value-metric-card"><div className="value-metric-top"><span className="value-metric-icon"><Icon name={item.key.includes('cost') ? 'circle-dollar-sign' : item.key.includes('time') ? 'clock' : item.key.includes('risk') ? 'shield-check' : 'activity'} size={16} /></span><StatusBadge tone={valueBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge></div><strong>{valueMetricText(item)}</strong><small>{item.label}</small><em>{item.detail}</em></div>
}

export function ValueIntelligence({ onToast }: { onToast: (message: string) => void }) {
  const [snapshot, setSnapshot] = useState<ValueIntelligenceSnapshot | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [eventOpen, setEventOpen] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [eventForm, setEventForm] = useState({ department: 'Operations', kind: 'decision_accelerated', title: '', linkedResource: '', evidence: '', status: 'not_measured', confidence: 'UNKNOWN', attribution: 'UNKNOWN', minutesSaved: '', valueUsd: '', costUsd: '', beforeValue: '', afterValue: '', metricLabel: 'Tracked metric', metricUnit: 'value' })
  const load = () => { setLoading(true); setError(''); api.valueIntelligence().then(setSnapshot).catch((caught) => setError(caught instanceof Error ? caught.message : 'Value intelligence could not be loaded.')).finally(() => setLoading(false)) }
  useEffect(() => { load() }, [])
  const submitValueEvent = async (event: FormEvent) => { event.preventDefault(); setSubmitting(true); try { await api.recordValueEvent({ department: eventForm.department, kind: eventForm.kind, title: eventForm.title, linkedResource: eventForm.linkedResource, evidence: splitLines(eventForm.evidence), status: eventForm.status, confidence: eventForm.confidence, attribution: eventForm.attribution, minutesSaved: eventForm.minutesSaved ? Number(eventForm.minutesSaved) : null, valueUsd: eventForm.valueUsd ? Number(eventForm.valueUsd) : null, costUsd: eventForm.costUsd ? Number(eventForm.costUsd) : null, before: eventForm.beforeValue ? [{ key: 'tracked_metric', label: eventForm.metricLabel, value: Number(eventForm.beforeValue), unit: eventForm.metricUnit }] : [], after: eventForm.afterValue ? [{ key: 'tracked_metric', label: eventForm.metricLabel, value: Number(eventForm.afterValue), unit: eventForm.metricUnit }] : [] }); setEventOpen(false); load(); onToast('Value event recorded with explicit provenance.') } catch (caught) { onToast(caught instanceof Error ? caught.message : 'Value event could not be recorded.') } finally { setSubmitting(false) } }
  if (loading && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 9 · VALUE INTELLIGENCE" title="Prove value, do not count activity" description="Loading outcome-linked metrics and evidence gaps." /><LoadingBlock lines={8} /></div>
  if (error && !snapshot) return <div className="view-stack"><SectionHeading eyebrow="PHASE 9 · VALUE INTELLIGENCE" title="Prove value, do not count activity" description="Value intelligence stays separate from operational execution." /><ErrorNotice message={error} onRetry={load} /></div>
  if (!snapshot) return null
  const scoreItems = [snapshot.scores.enterpriseValue, snapshot.scores.aiRoi, snapshot.scores.customerValue, snapshot.scores.productHealth, snapshot.scores.businessHealth]
  return <div className="view-stack value-intelligence-view">
    <SectionHeading eyebrow="PHASE 9 · ENTERPRISE VALUE INTELLIGENCE" title="Prove value, do not count activity" description="Connect AI activity to successful work, measurable impact and defensible expansion decisions." action={<div className="heading-actions"><Button variant="secondary" icon="refresh" onClick={load}>Refresh value</Button><Button icon="plus" onClick={() => setEventOpen(true)}>Record value evidence</Button></div>} />
    <div className="value-notice"><span className="value-notice-icon"><Icon name="circle-dollar-sign" size={17} /></span><div><strong>{snapshot.scope.environment}</strong><p>{snapshot.scope.notice}</p></div><StatusBadge tone="warning">Activity ≠ value</StatusBadge></div>
    <div className="value-score-grid">{scoreItems.map((item) => <div className="value-score-card" key={item.key}><span>{item.label}</span><strong>{item.value === null ? 'Not measured' : `${item.value}/100`}</strong><StatusBadge tone={valueBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge><small>{item.detail}</small></div>)}</div>
    <div className="value-chain">{snapshot.valueChain.map((item, index) => <div className="value-chain-stage" key={item.stage}><span>{String(index + 1).padStart(2, '0')}</span><strong>{item.stage}</strong><StatusBadge tone={valueBadgeTone(item.status)}>{item.status.replaceAll('_', ' ')}</StatusBadge><small>{item.evidence}</small>{index < snapshot.valueChain.length - 1 && <Icon name="arrow-right" size={13} />}</div>)}</div>
    <div className="value-metric-grid">{snapshot.summary.map((item) => <ValueMetricCard item={item} key={item.key} />)}</div>
    <div className="value-grid value-grid-wide"><Panel><PanelTitle icon="activity" title="AI activity versus business value" detail={snapshot.activity.detail} /><div className="value-activity-table"><div><span>AI requests</span><strong>{snapshot.activity.aiRequests.value ?? 'Not measured'}</strong><StatusBadge tone={valueBadgeTone(snapshot.activity.aiRequests.status)}>{snapshot.activity.aiRequests.status.replaceAll('_', ' ')}</StatusBadge></div><div><span>Successful answers</span><strong>{snapshot.activity.successfulAnswers.value ?? 'Not measured'}</strong><StatusBadge tone="neutral">Outcome needed</StatusBadge></div><div><span>Value events</span><strong>{snapshot.activity.valueEvents.value ?? 'Not measured'}</strong><StatusBadge tone={valueBadgeTone(snapshot.activity.valueEvents.status)}>{snapshot.activity.valueEvents.status.replaceAll('_', ' ')}</StatusBadge></div><div><span>Activity → measured value</span><strong>{snapshot.activity.valueConversion.value === null ? 'Not measured' : `${snapshot.activity.valueConversion.value}%`}</strong><StatusBadge tone="neutral">No ROI shortcut</StatusBadge></div></div><div className="value-footnote"><Icon name="info" size={13} /> A conversation, document count or thumbs-up is not a value event until the task and outcome are verified.</div></Panel><Panel><PanelTitle icon="circle-dollar-sign" title="Cost versus value" detail="Invoice-linked cost is required before ROI" /><div className="value-cost-list"><div><span>Model cost</span><strong>{valueMetricText(snapshot.cost.modelCost)}</strong></div><div><span>Cost per request</span><strong>{valueMetricText(snapshot.cost.costPerRequest)}</strong></div><div><span>Cost per successful outcome</span><strong>{valueMetricText(snapshot.cost.costPerSuccessfulOutcome)}</strong></div><div><span>Cost per workflow</span><strong>{valueMetricText(snapshot.cost.costPerWorkflow)}</strong></div></div><div className="value-footnote"><Icon name="info" size={13} /> {snapshot.cost.detail}</div></Panel></div>
    <div className="value-grid value-grid-wide"><Panel><PanelTitle icon="users" title="Department value hypotheses" detail="No department ROI is claimed without a baseline" /><div className="department-value-list">{snapshot.departments.map((department) => <div key={department.department}><span className="department-value-avatar">{department.department.slice(0, 2).toUpperCase()}</span><span><strong>{department.department}</strong><small>{department.primaryUseCase}</small><em>{department.strongestSignal}</em></span><StatusBadge tone={valueBadgeTone(department.recommendation)}>{department.recommendation.replaceAll('_', ' ')}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="shield-check" title="Customer health" detail="Healthy, at-risk and growth segments need real cohorts" action={<StatusBadge tone="neutral">{snapshot.customerHealth.status.replaceAll('_', ' ')}</StatusBadge>} /><div className="customer-health-list">{snapshot.customerHealth.segments.map((segment) => <div key={segment.key}><span><strong>{segment.label}</strong><small>{segment.evidence}</small></span><b>{segment.count === null ? '—' : segment.count}</b></div>)}</div><div className="value-footnote"><Icon name="info" size={13} /> {snapshot.customerHealth.detail}</div></Panel></div>
    <Panel><PanelTitle icon="grid" title="Feature portfolio value" detail="Keep product complexity proportional to verified value" /><div className="feature-value-table"><div className="feature-value-row feature-value-head"><span>Capability</span><span>Portfolio</span><span>AI quality</span><span>Business value</span><span>Decision</span></div>{snapshot.featurePortfolio.map((feature) => <div className="feature-value-row" key={feature.key}><span><strong>{feature.feature}</strong><small>{feature.rationale}</small></span><StatusBadge tone={valueBadgeTone(feature.portfolio)}>{feature.portfolio.replaceAll('_', ' ')}</StatusBadge><StatusBadge tone={valueBadgeTone(feature.aiQuality.status)}>{feature.aiQuality.value === null ? 'Not measured' : `${feature.aiQuality.value}/100`}</StatusBadge><StatusBadge tone={valueBadgeTone(feature.businessValue.status)}>{feature.businessValue.value === null ? 'Not measured' : feature.businessValue.value}</StatusBadge><strong className="feature-decision">{feature.recommendation}</strong></div>)}</div></Panel>
    <div className="value-grid value-grid-wide"><Panel><PanelTitle icon="flask" title="Value experiments" detail="Small, falsifiable and outcome-linked" /><div className="value-experiment-list">{snapshot.experiments.map((experiment) => <div key={experiment.id}><span className="value-experiment-icon"><Icon name="flask" size={14} /></span><span><strong>{experiment.hypothesis}</strong><small>{experiment.targetUsers} · {experiment.duration} · {experiment.cost}</small><em>Success: {experiment.successCriteria[0]}</em></span><StatusBadge tone={valueBadgeTone(experiment.status)}>{experiment.status.replaceAll('_', ' ')}</StatusBadge></div>)}</div></Panel><Panel><PanelTitle icon="globe" title="Strategic scenarios" detail="Planning scenarios, not forecasts" /><div className="scenario-list">{snapshot.scenarios.map((scenario) => <div key={scenario.id}><strong>{scenario.scenario}</strong><small>{scenario.response}</small><em>Risk: {scenario.risk} · indicator: {scenario.leadingIndicator}</em></div>)}</div></Panel></div>
    <Panel><PanelTitle icon="lightbulb" title="Why customers would pay" detail="Business case with explicit uncertainty" /><div className="business-case-grid"><div><span>Problem</span><strong>{snapshot.businessCase.problem}</strong></div><div><span>Buyer</span><strong>{snapshot.businessCase.buyer}</strong></div><div><span>Reason to pay</span><strong>{snapshot.businessCase.reasonToPay}</strong></div><div><span>Value received</span><strong>{snapshot.businessCase.valueReceived}</strong></div><div><span>Retention</span><strong>{snapshot.businessCase.retention}</strong></div><div><span>Expansion</span><strong>{snapshot.businessCase.expansion}</strong></div></div><div className="value-footnote"><Icon name="shield" size={13} /> What could destroy the advantage: {snapshot.businessCase.advantageRisk}</div></Panel>
    <div className="value-recommendation"><Icon name="arrow-up-right" size={16} /><span><strong>Current answer: expansion is not yet proven.</strong><small>Invest first in outcome-linked telemetry, identity/connector/action trust and the smallest number of department experiments capable of producing measured value.</small></span><StatusBadge tone="warning">Evidence required</StatusBadge></div>
    {eventOpen && <div className="modal-backdrop" onClick={() => setEventOpen(false)}><div className="modal-card value-modal" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><div className="eyebrow">VALUE EVENT</div><h2>Record evidence, not activity</h2><p>Measured values require a source, baseline, attribution and reviewer-approved outcome.</p></div><button className="modal-close inline" onClick={() => setEventOpen(false)}><Icon name="x" size={18} /></button></div><form onSubmit={submitValueEvent}><div className="operating-form-grid"><label className="field-label">Department<input required value={eventForm.department} onChange={(event) => setEventForm({ ...eventForm, department: event.target.value })} /></label><label className="field-label">Event kind<select value={eventForm.kind} onChange={(event) => setEventForm({ ...eventForm, kind: event.target.value })}><option value="question_resolved">Question resolved</option><option value="manual_task_eliminated">Manual task eliminated</option><option value="workflow_completed">Workflow completed</option><option value="approval_accelerated">Approval accelerated</option><option value="decision_accelerated">Decision accelerated</option><option value="knowledge_gap_closed">Knowledge gap closed</option><option value="risk_identified">Risk identified</option><option value="risk_mitigated">Risk mitigated</option></select></label></div><label className="field-label">Title<input required value={eventForm.title} onChange={(event) => setEventForm({ ...eventForm, title: event.target.value })} maxLength={240} /></label><label className="field-label">Linked task, decision or workflow<input required value={eventForm.linkedResource} onChange={(event) => setEventForm({ ...eventForm, linkedResource: event.target.value })} maxLength={240} /></label><label className="field-label">Evidence <small>one reference per line</small><textarea required value={eventForm.evidence} onChange={(event) => setEventForm({ ...eventForm, evidence: event.target.value })} maxLength={4000} /></label><div className="operating-form-grid"><label className="field-label">Metric label<input required value={eventForm.metricLabel} onChange={(event) => setEventForm({ ...eventForm, metricLabel: event.target.value })} maxLength={160} /></label><label className="field-label">Unit<input required value={eventForm.metricUnit} onChange={(event) => setEventForm({ ...eventForm, metricUnit: event.target.value })} maxLength={40} /></label></div><div className="operating-form-grid"><label className="field-label">Before value<input type="number" value={eventForm.beforeValue} onChange={(event) => setEventForm({ ...eventForm, beforeValue: event.target.value })} /></label><label className="field-label">After value<input type="number" value={eventForm.afterValue} onChange={(event) => setEventForm({ ...eventForm, afterValue: event.target.value })} /></label></div><div className="operating-form-grid"><label className="field-label">Status<select value={eventForm.status} onChange={(event) => setEventForm({ ...eventForm, status: event.target.value })}><option value="not_measured">Not measured</option><option value="estimated">Estimated</option><option value="projected">Projected</option><option value="measured">Measured</option></select></label><label className="field-label">Attribution<select value={eventForm.attribution} onChange={(event) => setEventForm({ ...eventForm, attribution: event.target.value })}><option>UNKNOWN</option><option>ESTIMATED</option><option>PARTIALLY_ATTRIBUTABLE</option><option>STRONGLY_ASSOCIATED</option><option>DIRECT</option></select></label></div><div className="operating-form-grid"><label className="field-label">Minutes saved<input type="number" min="0" value={eventForm.minutesSaved} onChange={(event) => setEventForm({ ...eventForm, minutesSaved: event.target.value })} /></label><label className="field-label">Value USD<input type="number" min="0" step="0.01" value={eventForm.valueUsd} onChange={(event) => setEventForm({ ...eventForm, valueUsd: event.target.value })} /></label></div><div className="modal-actions"><Button variant="secondary" onClick={() => setEventOpen(false)}>Cancel</Button><Button type="submit" icon="badge-check" disabled={submitting}>{submitting ? 'Saving…' : 'Record value event'}</Button></div></form></div></div>}
  </div>
}
